<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import InputFilter from '@/components/Filter/InputFilter.vue'
import DateRangePickerOption from '@/components/Input/DateRangePickerOption.vue'
import Dropdown from '@/components/Dropdown/InputDropdown.vue'
import InputSearch from '@/components/Input/InputSearch.vue'
import Button from '@/components/Button/Button.vue'

// Real Case State & Data
const rcFilterJenis = ref('')
const rcFilterSearch = ref('')

const rcJenisOptions = [
  { value: '', text: 'Semua Jenis Transaksi' },
  { value: 'Pelunasan Penuh', text: 'Pelunasan Penuh Agunan Emas' },
  { value: 'Perpanjangan Sewa Modal', text: 'Perpanjangan Akad Sewa Modal' },
  { value: 'Cicil Sebagian', text: 'Pembayaran Cicilan Sebagian' }
]

const masterKasirList = [
  { tgl: '12/09/2026 09:15', sbg: '10234-26-01-000911', jenis: 'Pelunasan Penuh', nominal: 'Rp 8.750.000', rawNominal: 8750000, kasir: 'Rian Pratama' },
  { tgl: '12/09/2026 10:30', sbg: '10234-26-01-000912', jenis: 'Perpanjangan Sewa Modal', nominal: 'Rp 450.000', rawNominal: 450000, kasir: 'Dewi Sartika' },
  { tgl: '12/09/2026 11:45', sbg: '10234-26-01-000913', jenis: 'Pelunasan Penuh', nominal: 'Rp 14.200.000', rawNominal: 14200000, kasir: 'Rian Pratama' },
  { tgl: '12/09/2026 13:20', sbg: '10234-26-01-000914', jenis: 'Perpanjangan Sewa Modal', nominal: 'Rp 720.000', rawNominal: 720000, kasir: 'Ahmad Fauzi' },
  { tgl: '12/09/2026 14:10', sbg: '10234-26-01-000915', jenis: 'Pelunasan Penuh', nominal: 'Rp 22.500.000', rawNominal: 22500000, kasir: 'Dewi Sartika' }
]

const filteredKasirList = computed(() => {
  return masterKasirList.filter(item => {
    const matchesJenis = !rcFilterJenis.value || item.jenis === rcFilterJenis.value
    const matchesSearch = !rcFilterSearch.value ||
      item.sbg.toLowerCase().includes(rcFilterSearch.value.toLowerCase()) ||
      item.kasir.toLowerCase().includes(rcFilterSearch.value.toLowerCase())
    return matchesJenis && matchesSearch
  })
})

const totalKasirNominal = computed(() => {
  const sum = filteredKasirList.value.reduce((acc, curr) => acc + curr.rawNominal, 0)
  return 'Rp ' + sum.toLocaleString('id-ID')
})

const resetScenarioData = () => {
  rcFilterJenis.value = ''
  rcFilterSearch.value = ''
}

const loadScenarioData = () => {
  rcFilterJenis.value = 'Pelunasan Penuh'
  rcFilterSearch.value = ''
}

const setPresetFilter = (jenis, kasir) => {
  rcFilterJenis.value = jenis
  rcFilterSearch.value = kasir
}

// Lifecycle Demo State
const filterModel1 = ref({
  startDate: '',
  endDate: '',
  selectedOption: '1'
})

const handleFilterDate = (val) => {
  console.log('Filter date changed:', val)
}

const inputFilterProps = [
  {
    name: 'modelValue',
    type: 'Object',
    default: '{}',
    description: 'Objek konfigurasi filter yang berisi startDate, endDate, dan pilihan radio (wajib disertakan).'
  },
  {
    name: 'label',
    type: 'String',
    default: "'Test Label'",
    description: 'Label keterangan di atas kolom dropdown filter.'
  },
  {
    name: '@filterDate',
    type: 'Event (String)',
    default: '-',
    description: 'Event yang dipancarkan saat rentang tanggal filter dipilih atau diperbarui oleh pengguna.'
  }
]
</script>
