    <!-- CARD 3: Technical Specification & Props Matrix -->
    <DocCard
      title="Technical Specification & Props Matrix"
      description="Referensi lengkap spesifikasi antarmuka API, tipe data, nilai default, dan perilaku untuk DateRangePicker."
      badge="API Reference"
    >
      <PropsTable :items="dateRangePickerProps" />
