<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import DateRangePicker from '@/components/Input/DateRangePicker.vue'

// Real-world scenario state
const rcStartRange = ref('2026-08-15')
const rcEndRange = ref('2026-09-02')

function resetScenarioData() {
  rcStartRange.value = ''
  rcEndRange.value = ''
}

function loadScenarioData() {
  rcStartRange.value = '2026-09-01'
  rcEndRange.value = '2026-09-30'
}

function setQuickRange(start, end) {
  rcStartRange.value = start
  rcEndRange.value = end
}

const isRangeValid = computed(() => {
  return Boolean(rcStartRange.value && rcEndRange.value)
})

const rangeDurationDays = computed(() => {
  if (!rcStartRange.value || !rcEndRange.value) return 0
  const s = new Date(rcStartRange.value)
  const e = new Date(rcEndRange.value)
  if (isNaN(s.getTime()) || isNaN(e.getTime())) return 0
  const diff = Math.round((e.getTime() - s.getTime()) / (1000 * 60 * 60 * 24))
  return diff >= 0 ? diff + 1 : 0
})

const calculatedWorkingDays = computed(() => {
  if (!rangeDurationDays.value) return 0
  return Math.round(rangeDurationDays.value * (5 / 7))
})

const calculatedDocCount = computed(() => {
  if (!rangeDurationDays.value) return 0
  return rangeDurationDays.value * 12
})

// Lifecycle states
const stateStartDefault = ref('')
const stateEndDefault = ref('')

const stateStartPreselected = ref('2026-08-01')
const stateEndPreselected = ref('2026-08-31')

const stateStartDisabled = ref('2026-01-01')
const stateEndDisabled = ref('2026-01-31')

const stateStartError = ref('2026-01-01')
const stateEndError = ref('2026-06-30')

// Props Matrix Documentation
const dateRangePickerProps = [
  {
    name: 'v-model:startDate',
    type: 'String',
    default: "''",
    description: 'Binding data tanggal awal rentang waktu (format: YYYY-MM-DD).'
  },
  {
    name: 'v-model:endDate',
    type: 'String',
    default: "''",
    description: 'Binding data tanggal akhir rentang waktu (format: YYYY-MM-DD).'
  },
  {
    name: 'firstLabel',
    type: 'String',
    default: "'Tanggal Awal'",
    description: 'Label judul untuk kolom tanggal awal.'
  },
  {
    name: 'secondLabel',
    type: 'String',
    default: "'Tanggal Akhir'",
    description: 'Label judul untuk kolom tanggal akhir.'
  },
  {
    name: 'separator',
    type: 'Boolean',
    default: 'false',
    description: 'Menampilkan elemen pemisah teks "s.d" di antara kedua kalender.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan kedua input kalender secara bersamaan.'
  },
  {
    name: 'errorMessage',
    type: 'String',
    default: "''",
    description: 'Pesan validasi kesalahan kustom yang ditampilkan di bawah rentang tanggal.'
  },
  {
    name: 'flexWidth',
    type: 'Boolean',
    default: 'false',
    description: 'Mengatur lebar input agar fleksibel mengikuti 50% kontainer parent.'
  }
]
</script>
