<script setup>
/**
 * LoadAnimation.section.vue
 * Standardized 3-Card Enterprise Architecture Showcase for <Load />
 */
defineOptions({
  name: 'LoadAnimationSection'
})

import { ref } from 'vue'
import Load from '@/components/Modal/Load.vue'
import Button from '@/components/Button/Button.vue'
import DocCard from '../components/DocCard.vue'
import PropsTable from '../components/PropsTable.vue'

// Varian Interactive State Loaders
const showDefaultLoader = ref(false)
const showProgressLoader = ref(false)
const progressPercent = ref(0)
const showSyncLoader = ref(false)
const showCompletedLoader = ref(false)
const showNonPersistentLoader = ref(false)

const triggerDefaultLoader = () => {
  showDefaultLoader.value = true
  setTimeout(() => {
    showDefaultLoader.value = false
  }, 2500)
}

const triggerProgressLoader = () => {
  showProgressLoader.value = true
  progressPercent.value = 0
  const interval = setInterval(() => {
    if (progressPercent.value < 100) {
      progressPercent.value += 20
    } else {
      clearInterval(interval)
      setTimeout(() => {
        showProgressLoader.value = false
      }, 500)
    }
  }, 300)
}

const triggerSyncLoader = () => {
  showSyncLoader.value = true
  setTimeout(() => {
    showSyncLoader.value = false
  }, 2500)
}

const triggerCompletedLoader = () => {
  showCompletedLoader.value = true
  setTimeout(() => {
    showCompletedLoader.value = false
  }, 2000)
}

// Card 1: Real-World Business Scenario
const showRealCaseLoader = ref(false)
const realCaseProgress = ref(0)
const isTransferring = ref(false)
const transferStatusText = ref('Siap Diproses')
const activePreset = ref('bri')

const transferPresets = {
  bri: {
    sbgNumber: '#SBG-2026-9901',
    channelName: 'Bank BRI Core Gateway',
    recipientName: 'Bambang Sudiro',
    accountNumber: '0206-01-088192-50-2',
    transferAmount: 'Rp 25.000.000',
    trxRef: 'TRX-BRI-9901-PGD'
  },
  mandiri: {
    sbgNumber: '#SBG-2026-9904',
    channelName: 'Bank Mandiri Host-to-Host',
    recipientName: 'Hj. Siti Aminah',
    accountNumber: '120-00-1928374-1',
    transferAmount: 'Rp 50.000.000',
    trxRef: 'TRX-MDR-9904-PGD'
  },
  bca: {
    sbgNumber: '#SBG-2026-9908',
    channelName: 'Bank BCA RTGS Switch',
    recipientName: 'PT Cahaya Emas Lestari',
    accountNumber: '882-019-3321',
    transferAmount: 'Rp 120.000.000',
    trxRef: 'TRX-BCA-9908-PGD'
  }
}

const currentCase = ref({ ...transferPresets.bri })

function applyPreset(presetKey) {
  activePreset.value = presetKey
  currentCase.value = { ...transferPresets[presetKey] }
  transferStatusText.value = 'Siap Diproses'
  realCaseProgress.value = 0
}

function resetScenarioData() {
  activePreset.value = 'bri'
  currentCase.value = { ...transferPresets.bri }
  transferStatusText.value = 'Siap Diproses'
  realCaseProgress.value = 0
}

function loadScenarioData() {
  applyPreset('mandiri')
  transferStatusText.value = 'Data Mandiri Rp 50.000.000 siap ditransmisikan.'
}

function startRealCaseTransfer() {
  isTransferring.value = true
  showRealCaseLoader.value = true
  realCaseProgress.value = 15
  transferStatusText.value = 'Sedang Mengontak Gateway Perbankan...'

  const stepInterval = setInterval(() => {
    if (realCaseProgress.value < 100) {
      realCaseProgress.value += 25
    } else {
      clearInterval(stepInterval)
      setTimeout(() => {
        showRealCaseLoader.value = false
        isTransferring.value = false
        transferStatusText.value = `Selesai — Dana ${currentCase.value.transferAmount} Berhasil Ditransfer ke Rekening ${currentCase.value.recipientName}.`
      }, 600)
    }
  }, 400)
}

// Card 3: Props Specification Matrix
const loadAnimationProps = [
  {
    name: 'v-model',
    type: 'Boolean',
    default: 'false',
    description: 'Mengontrol kemunculan dialog modal loader (two-way binding via modelValue).'
  },
  {
    name: 'title',
    type: 'String',
    default: "'Memproses Data'",
    description: 'Teks status pesan yang ditampilkan di bawah animasi bulatan memantul.'
  },
  {
    name: 'count',
    type: 'Number',
    default: '0',
    description: 'Nilai angka persentase proses (bila > 0, otomatis merender label count + %).'
  },
  {
    name: 'persistent',
    type: 'Boolean',
    default: 'true',
    description: 'Mencegah dialog loader tertutup tanpa sengaja saat proses transaksi belum tuntas.'
  }
]
</script>

<style scoped lang="scss">
.inline-loader {
