<script setup>
defineOptions({
  name: 'TabGroupSection'
})

import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import TabGroup from '@/components/Tab/TabGroup.vue'
import Button from '@/components/Button/Button.vue'

const tabsProduk = ref([
  { label: 'Gadai KCA Emas', active: true, action: () => '/' },
  { label: 'Krasida Usaha', active: false, action: () => '/' },
  { label: 'Tabungan Emas', active: false, action: () => '/' }
])

const tabsStatus = ref([
  { label: 'Semua Status', active: true, action: () => '/' },
  { label: 'Lunas Selesai', active: false, action: () => '/' },
  { label: 'Jatuh Tempo Lelang', active: false, action: () => '/' }
])

const rcKasTabs = ref([
  {
    label: 'Pencairan Pinjaman',
    active: true,
    action: () => setRcTab(0)
  },
  {
    label: 'Pelunasan Tebusan',
    active: false,
    action: () => setRcTab(1)
  },
  {
    label: 'Sewa Modal & Denda',
    active: false,
    action: () => setRcTab(2)
  }
])

const setRcTab = (idx) => {
  rcKasTabs.value.forEach((t, i) => {
    t.active = (i === idx)
  })
}

const activeRcTabLabel = computed(() => {
  const active = rcKasTabs.value.find(t => t.active)
  return active ? active.label : 'Pencairan Pinjaman'
})

const resetRcTabs = () => {
  setRcTab(0)
}

const loadRcTabs = () => {
  setRcTab(1)
}

const handleCetakJurnal = () => {
  alert('Mencetak rekapitulasi jurnal kas loket harian...')
}

const tabGroupProps = ref([
  {
    name: 'items',
    type: 'Array<Object>',
    default: '[title, title 2, title_3]',
    description: 'Daftar butir tab dengan skema { label: String, active: Boolean, action?: Function, icon?: String }.'
  }
])
</script>

