<script setup>
defineOptions({
  name: 'TabProductSection'
})

import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import TabProduct from '@/components/Tab/TabProduct.vue'
import Button from '@/components/Button/Button.vue'

import icoTabungan from '@/assets/images/ico-tabungan-emas.svg'
import icoGadai from '@/assets/images/ico-gadai.svg'
import icoCicil from '@/assets/images/ico-cicil-emas.svg'
import icoHaji from '@/assets/images/ico-haji.svg'
import icoKendaraan from '@/assets/images/ico-kendaraan.svg'
import icoPembiayaan from '@/assets/images/ico-pembiayaan.svg'

const syariahProducts = ref([
  { label: 'Rahn Emas', active: true, action: '#rahn', icon: icoGadai },
  { label: 'Arrum Haji', active: false, action: '#haji', icon: icoHaji },
  { label: 'Amanah Kendaraan', active: false, action: '#kendaraan', icon: icoKendaraan },
  { label: 'Rahn Pembiayaan', active: false, action: '#pembiayaan', icon: icoPembiayaan }
])

const realCaseProducts = ref([
  {
    label: 'Tabungan Emas',
    active: true,
    action: () => setRcProduct(0),
    icon: icoTabungan
  },
  {
    label: 'Gadai KCA Emas',
    active: false,
    action: () => setRcProduct(1),
    icon: icoGadai
  },
  {
    label: 'Cicil Logam Mulia',
    active: false,
    action: () => setRcProduct(2),
    icon: icoCicil
  },
  {
    label: 'Pembiayaan Usaha',
    active: false,
    action: () => setRcProduct(3),
    icon: icoPembiayaan
  }
])

const setRcProduct = (idx) => {
  realCaseProducts.value.forEach((p, i) => {
    p.active = (i === idx)
  })
}

const activeRcProduct = computed(() => {
  return realCaseProducts.value.find(p => p.active)
})

const resetRcProduct = () => {
  setRcProduct(0)
}

const loadRcProduct = () => {
  setRcProduct(1)
}

const handleBukaProduk = () => {
  alert(`Membuka formulir pengajuan produk ${activeRcProduct.value?.label || 'Tabungan Emas'}...`)
}

const tabProductProps = ref([
  {
    name: 'items',
    type: 'Array<Object>',
    default: '6 Produk Default',
    description: 'Daftar butir kartu produk dengan skema { label: String, active: Boolean, action: Function|String, icon: String }.'
  }
])
