const currentPaged = ref(1)
const perPageReal = ref(3)
const allTransactions = ref([
  { id: 1, time: '08:15 WIB', receipt: 'KW-001/09/26', teller: 'Indra Gunawan', type: 'Pelunasan Sewa Modal', amount: '1.250.000' },
  { id: 2, time: '08:42 WIB', receipt: 'KW-002/09/26', teller: 'Indra Gunawan', type: 'Perpanjangan Masa Gadai', amount: '450.000' },
  { id: 3, time: '09:10 WIB', receipt: 'KW-003/09/26', teller: 'Sari Rahayu', type: 'Pencairan Gadai Emas', amount: '15.000.000' },
  { id: 4, time: '09:55 WIB', receipt: 'KW-004/09/26', teller: 'Indra Gunawan', type: 'Pembelian Tabungan Emas', amount: '500.000' },
  { id: 5, time: '10:30 WIB', receipt: 'KW-005/09/26', teller: 'Sari Rahayu', type: 'Pelunasan Cicilan Emasku', amount: '890.000' },
  { id: 6, time: '11:15 WIB', receipt: 'KW-006/09/26', teller: 'Indra Gunawan', type: 'Pelunasan Sewa Modal', amount: '3.400.000' },
