  { id: 8, time: '13:40 WIB', receipt: 'KW-008/09/26', teller: 'Indra Gunawan', type: 'Perpanjangan Masa Gadai', amount: '620.000' },
  { id: 9, time: '14:20 WIB', receipt: 'KW-009/09/26', teller: 'Sari Rahayu', type: 'Pelunasan Sewa Modal', amount: '2.100.000' }
])

const totalTransactions = computed(() => allTransactions.value.length)

const pagedTransactions = computed(() => {
  const start = (currentPaged.value - 1) * perPageReal.value
  return allTransactions.value.slice(start, start + perPageReal.value)
})

function resetScenarioData() {
  currentPaged.value = 1
}

function loadScenarioData() {
  currentPaged.value = 2
}

const tablePaginationProps = [
  {
    name: 'modelValue',
    type: 'Number',
    default: '1',
    isModel: true,
    description: 'Indeks nomor halaman yang sedang aktif saat ini (pengikatan dua arah v-model).'
  },
  {
    name: 'totalRows',
    type: 'Number',
    default: '-',
    description: 'Total keseluruhan baris data yang ada di basis data / respons API.'
  },
  {
    name: 'perPage',
    type: 'Number',
    default: '-',
    description: 'Jumlah baris yang dialokasikan untuk tampil pada setiap satu lembar halaman.'
  },
  {
    name: 'limit',
    type: 'Number',
    default: '5',
    description: 'Batas maksimum jumlah nomor halaman yang ditampilkan sebelum dipersingkat dengan ellipsis.'
