<template>
    <div class="switch form-check form-switch custom-switch" style="padding: 0px;">
        <input 
            class="form-check-input" 
            type="checkbox" 
            :id="id" 
            :checked="modelValue" 
            @change="handleChange"
        >
        <label 
            tabindex="0"
            @keydown.enter.prevent="toggleValue" 
            class="custom-toggle" 
            :for="id">
        </label>
    </div>
</template>

<script>
    export default {
        name: "SwitchComponent",
        props: {
            id: {
                type: String,
                default: "switch",
            },
            modelValue: {
                type: Boolean,
                default: false,
            },
        },
        data() {
            return {
            isFocused: false,
            };
        },
        methods: {
            handleChange(event) {
                this.$emit('update:modelValue', event.target.checked);
            },
            toggleValue() {
                this.$emit("update:modelValue", !this.modelValue);
                },
        },
    };
</script>

<style scoped lang="scss">
