        }
    }
}

.form-check-input {
    opacity: 0;
    width: 0;
    height: 0;
    display: none;
}

.custom-toggle {
    position: relative;
    display: block;
    width: 36px; /* Width of the track */
    height: 16px; /* Height of the track */
    margin: 0 2px;
    background-color: var(--g-kit-black-40, #cbd5e1);
    border-radius: 10px;
    cursor: pointer;
