<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import FilterCMS from '@/components/Filter/FilterCMS.vue'
import Button from '@/components/Button/Button.vue'
import InputSearch from '@/components/Input/InputSearch.vue'
import Dropdown from '@/components/Dropdown/InputDropdown.vue'

// Date & Time Update
const today = new Date()
const dateUpdate = today.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })
const timeUpdate = new Intl.DateTimeFormat('id-ID', {
  hour: '2-digit',
  minute: '2-digit',
  hour12: false
}).format(today) + ' WIB'

// Real Case State & Data
const rcFilterQuery = ref('')
const rcFilterProduk = ref('')
const rcFilterStatus = ref('')

const masterOslData = [
  { id: 'OSL-2026-001', nasabah: 'Budi Santoso', produk: 'Gadai KCA', up: 'Rp 8.500.000', rawUp: 8500000, status: 'Lancar' },
  { id: 'OSL-2026-002', nasabah: 'Siti Aminah', produk: 'Gadai Krasida', up: 'Rp 15.000.000', rawUp: 15000000, status: 'Lancar' },
  { id: 'OSL-2026-003', nasabah: 'Ahmad Dahlan', produk: 'Gadai KCA', up: 'Rp 5.200.000', rawUp: 5200000, status: 'Jatuh Tempo' },
  { id: 'OSL-2026-004', nasabah: 'Rina Wijaya', produk: 'Tabungan Emas', up: 'Rp 12.000.000', rawUp: 12000000, status: 'Lancar' },
  { id: 'OSL-2026-005', nasabah: 'Hendro Prasetyo', produk: 'Gadai Bisnis', up: 'Rp 25.000.000', rawUp: 25000000, status: 'Jatuh Tempo' }
]

const produkOptions = [
  { value: '', text: 'Semua Produk Gadai' },
  { value: 'Gadai KCA', text: 'Gadai KCA (Kredit Cepat Aman)' },
  { value: 'Gadai Krasida', text: 'Gadai Krasida (Angsuran)' },
  { value: 'Tabungan Emas', text: 'Titipan Tabungan Emas' },
  { value: 'Gadai Bisnis', text: 'Gadai Usaha / Bisnis' }
]

const statusOptions = [
  { value: '', text: 'Semua Status' },
  { value: 'Lancar', text: 'Status Lancar' },
  { value: 'Jatuh Tempo', text: 'Jatuh Tempo / Peringatan' }
]

const filteredOslData = computed(() => {
  return masterOslData.filter(item => {
    const matchesQuery = !rcFilterQuery.value ||
      item.nasabah.toLowerCase().includes(rcFilterQuery.value.toLowerCase()) ||
      item.id.toLowerCase().includes(rcFilterQuery.value.toLowerCase())
    const matchesProduk = !rcFilterProduk.value || item.produk === rcFilterProduk.value
    const matchesStatus = !rcFilterStatus.value || item.status === rcFilterStatus.value
    return matchesQuery && matchesProduk && matchesStatus
  })
})

const totalOslNominal = computed(() => {
  const sum = filteredOslData.value.reduce((acc, curr) => acc + curr.rawUp, 0)
  return 'Rp ' + sum.toLocaleString('id-ID')
})

const resetScenarioData = () => {
  rcFilterQuery.value = ''
  rcFilterProduk.value = ''
  rcFilterStatus.value = ''
}

const loadScenarioData = () => {
  rcFilterQuery.value = ''
  rcFilterProduk.value = 'Gadai KCA'
  rcFilterStatus.value = 'Lancar'
}

const setFilterPreset = (q, produk, status) => {
  rcFilterQuery.value = q
  rcFilterProduk.value = produk
  rcFilterStatus.value = status
}

const exportDataSimulasi = () => {
  alert(`Mengekspor ${filteredOslData.value.length} data portofolio OSL terpilih...`)
}

// State untuk Lifecycle Demo
const v1JenisPengajuan = ref('')
const v1KategoriAgunan = ref('')
const v1Kanwil = ref('')
const v1StatusOtorisasi = ref('')
const v1Query = ref('')
const v1MetodePelunasan = ref('')

const v2Search = ref('')
const v2Loket = ref('')
const v2StatusLayanan = ref('')

const pengajuanOptions = [
  { value: '', text: 'Semua Pengajuan Kredit' },
  { value: 'kca', text: 'Gadai KCA (Kredit Cepat Aman)' },
  { value: 'krasida', text: 'Gadai Krasida (Sistem Angsuran)' },
  { value: 'mulia', text: 'Investasi Logam Mulia' }
]

const agunanOptions = [
  { value: '', text: 'Semua Kategori Agunan' },
  { value: 'emas_perhiasan', text: 'Emas Perhiasan (18K - 24K)' },
  { value: 'logam_mulia', text: 'Logam Mulia / Batangan' },
  { value: 'elektronik', text: 'Barang Elektronik & Gadget' }
]

const kanwilOptions = [
  { value: '', text: 'Semua Kantor Wilayah' },
  { value: 'kanwil_jakarta1', text: 'Kanwil VIII Jakarta 1' },
  { value: 'kanwil_surabaya', text: 'Kanwil XII Surabaya' },
  { value: 'kanwil_medan', text: 'Kanwil I Medan' }
]

const otorisasiOptions = [
  { value: '', text: 'Semua Status Otorisasi' },
  { value: 'approved', text: 'Telah Disetujui Penaksir' },
  { value: 'pending', text: 'Menunggu Review Komite' }
]

const pembayaranOptions = [
  { value: '', text: 'Semua Metode Pembayaran' },
  { value: 'tunai', text: 'Setoran Tunai di Loket' },
  { value: 'transfer', text: 'Transfer Virtual Account (BSI/BRI)' }
]

const loketOptions = [
  { value: '', text: 'Semua Loket UPK' },
  { value: 'loket1', text: 'Loket 01 - Kasir Utama' },
  { value: 'loket2', text: 'Loket 02 - Penaksir Emas' }
]

const filterCMSProps = [
  {
    name: 'filter',
    type: 'Boolean',
    default: 'false',
    description: 'Mengaktifkan tombol toggle visual filter untuk menyembunyikan atau menampilkan panel kriteria.'
  },
  {
    name: '#update-text',
    type: 'Slot',
    default: '-',
    description: 'Area kiri atas bilah untuk menampilkan status operasional atau timestamp sinkronisasi data terakhir.'
  },
  {
    name: '#buttons',
    type: 'Slot',
    default: '-',
    description: 'Area kanan atas bilah untuk meletakkan tombol aksi batch (Ekspor, Cetak, Reset, dsb).'
  },
  {
    name: '#filters',
    type: 'Slot',
    default: '-',
    description: 'Area kontainer utama yang merapikan susunan input pencarian dan dropdown ke dalam grid proporsional.'
  }
]
</script>
