<script setup>
/**
 * @file PlaygroundFooter.vue
 * @description Enterprise-grade global footer for Kitvue Design System Playground.
 * Features obsidian styling, 4-column component directory, CLI quick scaffolding copy,
 * production readiness badges, and sticky floating back-to-top navigation with auto-hide on footer view.
 */
import { ref, onMounted, onUnmounted } from 'vue'

defineProps({
  totalComponents: {
    type: Number,
    default: 81
  },
  categories: {
    type: Array,
    default: () => []
  }
})

const emit = defineEmits(['navigate-category', 'navigate-component'])

const cliCommand = 'pnpm add @pegadaian/kitvue'
const isCopied = ref(false)
const currentYear = new Date().getFullYear()
const showFloatingBackToTop = ref(false)
const footerRef = ref(null)
let footerObserver = null

const copyCli = () => {
  if (typeof navigator !== 'undefined' && navigator.clipboard) {
    navigator.clipboard.writeText(cliCommand)
    isCopied.value = true
    setTimeout(() => {
      isCopied.value = false
    }, 2000)
  }
}

const scrollToTop = () => {
  window.scrollTo({
    top: 0,
    behavior: 'smooth'
  })
}

const handleWindowScroll = () => {
  const scrollY = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0

  // Check if footer is visible in the viewport
  let isFooterVisible = false
  if (footerRef.value) {
    const rect = footerRef.value.getBoundingClientRect()
    // If footer top is above the bottom of the viewport
    isFooterVisible = rect.top < (window.innerHeight - 20)
  }

  // Show floating button ONLY if scrolled down past threshold AND footer is NOT in view
  showFloatingBackToTop.value = scrollY > 320 && !isFooterVisible
}

onMounted(() => {
  window.addEventListener('scroll', handleWindowScroll, { passive: true })
  handleWindowScroll()

  if (footerRef.value && 'IntersectionObserver' in window) {
    footerObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          showFloatingBackToTop.value = false
        } else {
          const scrollY = window.pageYOffset || document.documentElement.scrollTop || 0
          showFloatingBackToTop.value = scrollY > 320
        }
      })
    }, { rootMargin: '0px 0px 40px 0px', threshold: 0 })
    footerObserver.observe(footerRef.value)
  }
})

onUnmounted(() => {
  window.removeEventListener('scroll', handleWindowScroll)
  if (footerObserver) {
    footerObserver.disconnect()
  }
})
</script>

