<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import RadioComponent from '@/components/Radio/Radio.vue'

// Real-world scenario state
const realCaseAkad = ref('kca')
const simulasiPlafon = ref(15000000)

const skemaAkadOptions = [
  { value: 'kca', label: 'KCA (Gadai Konvensional)' },
  { value: 'rahn', label: 'Rahn (Gadai Syariah)' },
  { value: 'krasida', label: 'Krasida (Gadai Angsuran)' }
]

function formatRupiah(num) {
  return 'Rp ' + Number(num || 0).toLocaleString('id-ID')
}

const akadDetails = computed(() => {
  switch (realCaseAkad.value) {
    case 'kca':
      return {
        nama: 'Kredit Cepat Aman (KCA)',
        legalBadge: 'POJK Terdaftar',
        rateInfo: '1.15% per 15 Hari',
        estimasiBiaya: Math.round(simulasiPlafon.value * 0.0115),
        tenorMax: '120 Hari (Perpanjang OK)',
        metodeBayar: 'Lunas saat jatuh tempo',
        regulasi: 'POJK No. 31/POJK.05/2016'
      }
    case 'rahn':
      return {
        nama: 'Gadai Rahn Syariah',
        legalBadge: 'DSN-MUI Syariah',
        rateInfo: '0.75% per 10 Hari (Mu\'nah)',
        estimasiBiaya: Math.round(simulasiPlafon.value * 0.0075),
        tenorMax: '120 Hari (Fleksibel)',
        metodeBayar: 'Ujrah mu\'nah proporsional',
        regulasi: 'Fatwa DSN-MUI No. 25'
      }
    case 'krasida':
      return {
        nama: 'Krasida (Angsuran Emas)',
        legalBadge: 'OJK Multifinance',
        rateInfo: '1.25% Flat per Bulan',
        estimasiBiaya: Math.round(simulasiPlafon.value * 0.0125),
        tenorMax: '12 - 36 Bulan',
        metodeBayar: 'Cicilan pokok + sewa per bulan',
        regulasi: 'POJK Layanan Gadai Angsuran'
      }
    default:
      return {
        nama: '-',
        legalBadge: '-',
        rateInfo: '-',
        estimasiBiaya: 0,
        tenorMax: '-',
        metodeBayar: '-',
        regulasi: '-'
      }
  }
})

function setAkadPreset(akad, nominal) {
  realCaseAkad.value = akad
  simulasiPlafon.value = nominal
}

function getAkadLabel(val) {
  const item = skemaAkadOptions.find(o => o.value === val)
  return item ? item.label : '-'
}

function getAkadPolicy(val) {
  switch (val) {
    case 'kca':
      return 'Sewa modal dihitung per 15 hari, jangka waktu standar 120 hari.'
    case 'rahn':
      return 'Biaya pemeliharaan barang (mu\'nah) dihitung per 10 hari sesuai DSN MUI.'
    case 'krasida':
      return 'Pembayaran pokok + sewa modal diangsur tetap tiap bulan (tenor 6-36 bulan).'
    default:
      return '-'
  }
}

function resetScenarioData() {
  realCaseAkad.value = 'kca'
  simulasiPlafon.value = 15000000
}

function loadScenarioData() {
  setAkadPreset('rahn', 25000000)
}

// Lifecycle states
const stateDefault = ref('ya')
const defaultBinaryItems = [
  { value: 'ya', label: 'Ya, Sesuai Fisik' },
  { value: 'tidak', label: 'Perlu Revisi' }
]

const statePencairan = ref('transfer')
const pencairanItems = [
  { value: 'kas', label: 'Tunai di Cabang' },
  { value: 'transfer', label: 'Transfer Bank' }
]

const stateLayanan = ref('reguler')
const layananItems = [
  { value: 'reguler', label: 'Layanan Reguler' },
  { value: 'prioritas', label: 'Layanan Prioritas', disabled: true }
]

const stateGroupDisabled = ref('ya')

// Props Matrix Documentation
const radioProps = [
  {
    name: 'items',
    type: 'Array<Object>',
    default: '[]',
    required: true,
    description: 'Daftar opsi radio dengan format { value, label/text, disabled }.'
  },
  {
    name: 'modelValue',
    type: 'String | Number | Boolean',
    default: 'null',
    isModel: true,
    description: 'Nilai aktif yang dipilih pengguna via two-way data binding (v-model).'
  },
  {
    name: 'defaultSelected',
    type: 'String | Number | Boolean',
    default: 'null',
    description: 'Nilai awal yang langsung terpilih saat komponen pertama kali dimuat.'
  },
  {
    name: 'name',
    type: 'String',
    default: 'auto-generated',
    description: 'Nama atribut kelompok HTML radio group untuk isolasi pemilihan dalam form.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan seluruh opsi radio group secara serentak.'
  },
  {
    name: 'activeIcon',
    type: 'String',
    default: 'SVG icon-radio-on',
    description: 'URL atau path gambar icon custom untuk status radio aktif/terpilih.'
  },
  {
    name: 'inactiveIcon',
    type: 'String',
    default: 'SVG icon-radio-off',
    description: 'URL atau path gambar icon custom untuk status radio tidak terpilih.'
  },
  {
    name: '#icon',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot kustomisasi indikator visual radio (scope: { item, checked, disabled, iconSrc }).'
  },
  {
    name: '#label',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot kustomisasi konten teks label opsi (scope: { item, checked, disabled }).'
  },
  {
    name: '@update:modelValue',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat pengguna memilih salah satu opsi radio.'
  },
  {
    name: '@change',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat nilai pilihan radio mengalami perubahan.'
  }
]
</script>
