<script setup>
/**
 * @file ModalBottomSheet.vue
 * @description Komponen modal/popup adaptif enterprise Pegadaian mengikuti pola implementasi resmi ModalSlider.vue.
 * - Pada layar Desktop (>= 576px): Merender <BModal> terpusat (centered modal dialog) dengan sudut 16px dan elevasi halus.
 * - Pada layar Mobile (< 576px): Merender <BOffcanvas placement="bottom"> yang merapat ke dasar layar (Bottom Sheet).
 * 
 * @prop {boolean} modelValue - Visibilitas dialog (v-model)
 * @prop {string} [title=''] - Judul header dialog
 * @prop {boolean} [persistent=false] - Mencegah dialog ditutup via backdrop / ESC
 * @prop {boolean} [closeOnOverlay=true] - Menutup dialog saat area backdrop/overlay luar diklik
 * @prop {boolean} [centered=true] - Memposisikan modal di tengah vertikal pada desktop
 * @prop {'sm' | 'md' | 'lg' | 'xl'} [size='sm'] - Dimensi lebar modal pada desktop
 * @prop {boolean} [showCloseButton=true] - Menampilkan tombol silang tutup
 * @prop {boolean} [showGrabber=true] - Menampilkan grabber pill bar saat di mobile bottom-sheet
 * @prop {boolean} [scrollable=false] - Mengaktifkan scroll pada body
 * @prop {'auto' | 'modal' | 'bottom-sheet'} [mode='auto'] - Kontrol adaptif otomatis atau pemaksaan mode
 * @prop {boolean} [hideDivider=false] - Menyembunyikan border pemisah header
 * 
 * @slot header - Kustomisasi bar header dialog modal / bottom sheet (scoped { close })
 * @slot body - Area konten utama dialog modal / bottom sheet (scoped { close, hide })
 * @slot default - Alias slot default konten modal (scoped { close, hide })
 * @slot footer - Bar aksi bawah dialog modal / bottom sheet (scoped { close, hide }). Otomatis tersembunyi jika tidak disediakan.
 * 
 * @emits update:modelValue - Mengubah state visibilitas dialog
 * @emits hide - Dipancarkan saat dialog mulai menutup
 * @emits hidden - Dipancarkan setelah dialog selesai menutup
 * @emits show - Dipancarkan saat dialog mulai membuka
 * @emits shown - Dipancarkan setelah dialog selesai membuka
 */
import { BModal, BOffcanvas } from 'bootstrap-vue-next'
import { ref, onMounted, onUnmounted, computed, watch } from 'vue'

defineOptions({ name: 'ModalBottomSheet' })

const props = defineProps({
  title: {
    type: String,
    default: ''
  },
  persistent: {
    type: Boolean,
    default: false
  },
  closeOnOverlay: {
    type: Boolean,
    default: true
  },
  centered: {
    type: Boolean,
    default: true
  },
  size: {
    type: String,
    default: 'sm',
    validator(value) {
      return ['sm', 'md', 'lg', 'xl'].includes(value)
    }
  },
  showCloseButton: {
    type: Boolean,
    default: true
  },
  showGrabber: {
    type: Boolean,
    default: true
  },
  scrollable: {
    type: Boolean,
    default: false
  },
  mode: {
    type: String,
    default: 'auto',
    validator(value) {
      return ['auto', 'modal', 'bottom-sheet'].includes(value)
    }
  },
  hideDivider: {
    type: Boolean,
    default: false
  }
})

const model = defineModel({ default: false })

const isDesktop = ref(true)

const handleResize = () => {
  isDesktop.value = window.innerWidth >= 576
}

const lockScroll = () => {
  if (typeof document === 'undefined') return
  document.documentElement.classList.add('modal-open')
  document.body.classList.add('modal-open')
  document.documentElement.style.setProperty('overflow', 'hidden', 'important')
  document.documentElement.style.setProperty('overflow-y', 'hidden', 'important')
  document.body.style.setProperty('overflow', 'hidden', 'important')
  document.body.style.setProperty('overflow-y', 'hidden', 'important')
}

const unlockScroll = () => {
  if (typeof document === 'undefined') return
  // Only remove if no other active modal/offcanvas is open
  const otherOpenModals = document.querySelectorAll('.modal.show:not(.modal-bs-closing), .offcanvas.show')
  if (otherOpenModals.length <= 1) {
    document.documentElement.classList.remove('modal-open')
    document.body.classList.remove('modal-open')
    document.documentElement.style.removeProperty('overflow')
    document.documentElement.style.removeProperty('overflow-y')
    document.body.style.removeProperty('overflow')
    document.body.style.removeProperty('overflow-y')
  }
}

watch(
  () => model.value,
  (isOpen) => {
    if (isOpen) {
      lockScroll()
    } else {
      unlockScroll()
    }
  },
  { immediate: true }
)

onMounted(() => {
  handleResize()
  window.addEventListener('resize', handleResize)
  if (model.value) {
    lockScroll()
  }
})

onUnmounted(() => {
  window.removeEventListener('resize', handleResize)
  unlockScroll()
})

const isDesktopView = computed(() => {
  if (props.mode === 'modal') return true
  if (props.mode === 'bottom-sheet') return false
  return isDesktop.value
})

const emit = defineEmits(['update:modelValue', 'hide', 'hidden', 'show', 'shown'])

const shouldPreventBackdropClose = computed(() => {
  if (props.persistent) return true
  if (props.closeOnOverlay === false) return true
  return false
})

const hide = () => {
  model.value = false
}

defineExpose({
  hide,
  close: hide
})
</script>

<template>
  <div>
    <!-- DESKTOP VIEW: BModal centered (Pola Resmi ModalSlider.vue) -->
    <BModal
      v-if="isDesktopView"
      :class="[
        'modal-responsive-component desktop',
        props.title && !props.hideDivider && 'border-bottom'
      ]"
      :size="props.size"
      v-model="model"
      :id="$attrs.id"
      :centered="props.centered"
      :title="props.title"
      :no-close-on-backdrop="shouldPreventBackdropClose"
      :no-close-on-esc="props.persistent"
      :scrollable="props.scrollable"
      :hide-footer="!$slots.footer"
      @hide="emit('hide', $event)"
      @hidden="emit('hidden', $event)"
      @show="emit('show', $event)"
      @shown="emit('shown', $event)"
    >
      <template #header="{ close }">
        <slot name="header" :close="close">
          <div class="d-flex justify-content-between align-items-center w-100">
            <h5 class="modal-title m-0">{{ props.title }}</h5>
            <button
              v-if="props.showCloseButton"
              type="button"
              class="btn-close"
              aria-label="Close"
              @click="close()"
            ></button>
          </div>
        </slot>
      </template>

      <div class="modal-responsive-body">
        <slot name="body" :hide="hide" :close="hide">
          <slot :hide="hide" :close="hide" />
        </slot>
      </div>

      <template v-slot:footer="{ hide }">
        <div class="modal-responsive-footer d-flex w-100 gap-2 p-3 sticky rounded-3" v-if="$slots.footer">
          <slot name="footer" :hide="hide" :close="hide"></slot>
        </div>
      </template>
    </BModal>

    <!-- MOBILE VIEW: BOffcanvas bottom-sheet (Pola Resmi ModalSlider.vue) -->
    <BOffcanvas
      v-else
      v-model="model"
      :class="[
        'modal-responsive-component mobile',
        props.title && !props.hideDivider && 'border-bottom'
      ]"
      placement="bottom"
      :no-close-on-backdrop="shouldPreventBackdropClose"
      :no-close-on-esc="props.persistent"
      header-close
      @hide="emit('hide', $event)"
      @hidden="emit('hidden', $event)"
      @show="emit('show', $event)"
      @shown="emit('shown', $event)"
    >
      <template #header>
        <div class="d-flex flex-column w-100">
          <div v-if="props.showGrabber" class="bottom-sheet-grabber-wrap w-100" aria-hidden="true">
            <div class="bottom-sheet-grabber-pill"></div>
          </div>
          <slot name="header" :close="hide">
            <div class="title-offcanvas d-flex flex-row justify-content-between align-items-center w-100">
              <h5 class="modal-title m-0">{{ props.title }}</h5>
              <button
                v-if="props.showCloseButton"
                type="button"
                class="btn-close ms-2"
                aria-label="Close"
                @click="model = false"
              ></button>
            </div>
          </slot>
        </div>
      </template>

      <!-- Grabber Pull Pill (Visible on Mobile Bottom Sheet) -->
       
      <div class="offcanvas-responsive-body">
        <slot name="body" :hide="hide" :close="hide">
          <slot :hide="hide" :close="hide" />
        </slot>
      </div>

      <template #footer>
        <div class="modal-responsive-footer d-flex w-100 gap-2 p-3 pt-0 sticky rounded-3" v-if="$slots.footer">
          <slot name="footer" :hide="hide" :close="hide"></slot>
        </div>
      </template>
    </BOffcanvas>
  </div>
</template>

