<script setup>
/**
 * ModalTrackingStatus.vue
 * Komponen modal dialog pelacak status pengajuan / transaksi Pegadaian
 * yang mengintegrasikan ModalBottomSheet adaptif (Desktop Modal ↔ Mobile BottomSheet)
 * dan TrackingStatus sesuai spesifikasi Figma dan standar komponen Pegadaian UI Kit.
 *
 * @prop {boolean} modelValue - Kontrol visibilitas modal (v-model)
 * @prop {string} title - Judul modal dialog (default: 'Detail Status')
 * @prop {Array<Object>} items - Daftar tahapan status
 * @prop {number} currentStep - Indeks tahapan yang sedang aktif (0-indexed)
 * @prop {boolean} persistent - Kunci modal agar tidak tertutup saat klik backdrop / ESC
 * @prop {boolean} centered - Memposisikan modal di tengah vertikal viewport pada desktop
 * @prop {boolean} scrollable - Konten body dapat di-scroll secara independen
 * @prop {string} size - Ukuran modal: 'sm' | 'md' | 'lg' | 'xl' (default: 'md')
 * @prop {boolean} showCloseButton - Tampilkan tombol silang di header (default: true)
 * @prop {boolean} showGrabber - Tampilkan drag grabber pill bar saat di mobile bottom-sheet
 * @prop {'auto' | 'modal' | 'bottom-sheet'} mode - Kontrol mode tampilan
 * @prop {boolean} useBottomSheet - Transformasi adaptif ke mobile Bottom Sheet (default: true)
 *
 * @slot header - Kustomisasi area header dialog
 * @slot footer - Kustomisasi area footer dialog
 * @slot icon - Kustomisasi ikon indikator langkah
 * @slot title - Kustomisasi judul langkah
 * @slot description - Kustomisasi deskripsi langkah
 * @slot timestamp - Kustomisasi waktu/tanggal langkah
 */
import { defineModel, ref, computed, onMounted, onUnmounted } from 'vue'
import ModalBottomSheet from '../Modal/ModalBottomSheet.vue'
import TrackingStatus from './TrackingStatus.vue'

defineOptions({
  name: 'ModalTrackingStatus'
})

const props = defineProps({
  title: {
    type: String,
    default: 'Detail Status'
  },
  items: {
    type: Array,
    default: () => []
  },
  currentStep: {
    type: Number,
    default: -1
  },
  persistent: {
    type: Boolean,
    default: false
  },
  centered: {
    type: Boolean,
    default: true
  },
  scrollable: {
    type: Boolean,
    default: true
  },
  size: {
    type: String,
    default: 'md'
  },
  showCloseButton: {
    type: Boolean,
    default: true
  },
  showGrabber: {
    type: Boolean,
    default: true
  },
  mode: {
    type: String,
    default: 'auto'
  },
  useBottomSheet: {
    type: Boolean,
    default: true
  }
})

const model = defineModel({
  type: Boolean,
  default: false
})

const isMobileScreen = ref(false)

const handleResize = () => {
  isMobileScreen.value = typeof window !== 'undefined' ? window.innerWidth < 768 : false
}

onMounted(() => {
  handleResize()
  window.addEventListener('resize', handleResize)
})

onUnmounted(() => {
  window.removeEventListener('resize', handleResize)
})

const effectiveMode = computed(() => {
  if (props.mode && props.mode !== 'auto') {
    return props.mode
  }
  if (props.useBottomSheet && isMobileScreen.value) {
    return 'bottom-sheet'
  }
  return 'auto'
})
</script>

<template>
  <ModalBottomSheet
    class="modal-tracking-status"
    v-model="model"
    :title="props.title"
    :size="props.size"
    :centered="props.centered"
    :persistent="props.persistent"
    :scrollable="props.scrollable"
    :show-close-button="props.showCloseButton"
    :show-grabber="props.showGrabber"
    :mode="effectiveMode"
  >
    <!-- Slot Header jika disediakan -->
    <template #header="{ close }" v-if="$slots.header">
      <slot name="header" :close="close" :title="props.title" />
    </template>

    <!-- Konten Body: TrackingStatus -->
    <template #body>
      <div class="tracking-modal-body-container">
        <TrackingStatus
          :items="props.items"
          :currentStep="props.currentStep"
        >
          <template #icon="slotProps">
            <slot name="icon" v-bind="slotProps" />
          </template>
          <template #title="slotProps">
            <slot name="title" v-bind="slotProps" />
          </template>
          <template #description="slotProps">
            <slot name="description" v-bind="slotProps" />
          </template>
          <template #timestamp="slotProps">
            <slot name="timestamp" v-bind="slotProps" />
          </template>
        </TrackingStatus>
      </div>
    </template>

    <!-- Slot Footer jika diperlukan aksi tambahan -->
    <template #footer="{ hide, close }" v-if="$slots.footer">
      <slot name="footer" :hide="hide" :close="close" />
    </template>
  </ModalBottomSheet>
</template>

<style lang="scss">
.modal-responsive-component.desktop .modal-dialog {
  max-width: 560px !important;
}

.modal-tracking-status {
  .tracking-modal-body-container {
    width: 100%;
  }
}
</style>

<style lang="scss" scoped>
:deep(.modal-responsive-component.desktop .modal-dialog) {
  max-width: 560px !important;
}
</style>
