<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import ContentTimePicker from '@/components/Input/ContentTimePicker.vue'

// Real-world scenario state
const caseHour = ref('10')
const caseMinute = ref('15')
const caseTime = ref('10:15')

function resetScenarioData() {
  caseHour.value = '08'
  caseMinute.value = '00'
  caseTime.value = '08:00'
}

function loadScenarioData() {
  caseHour.value = '14'
  caseMinute.value = '30'
  caseTime.value = '14:30'
}

function setQuickTime(h, m) {
  caseHour.value = h
  caseMinute.value = m
  caseTime.value = `${h}:${m}`
}

const handleCaseTime = (val) => {
  caseTime.value = typeof val === 'object' && val !== null ? (val.activeTime || '') : String(val || '')
}

const convertedAmPm = computed(() => {
  if (!caseTime.value || typeof caseTime.value !== 'string') return '10:15 AM'
  const parts = caseTime.value.split(':')
  let hour = parseInt(parts[0], 10)
  const minute = parts[1] || '00'
  const suffix = hour >= 12 ? 'PM' : 'AM'
  hour = hour % 12
  if (hour === 0) hour = 12
  return `${hour}:${minute} ${suffix}`
})

// Lifecycle states
const selectedTime1 = ref('')
const selectedTime2 = ref('')

const handleTime1 = (val) => {
  selectedTime1.value = typeof val === 'object' && val !== null ? (val.activeTime || '') : String(val || '')
}

const handleTime2 = (val) => {
  selectedTime2.value = typeof val === 'object' && val !== null ? (val.activeTime || '') : String(val || '')
}

// Props Matrix Documentation
const contentTimePickerProps = [
  {
    name: 'defaultHour',
    type: 'String',
    default: "'23'",
    description: 'Nilai inisialisasi jam awal yang aktif pada roda kiri (format 00 - 23).'
  },
  {
    name: 'defaultMinute',
    type: 'String',
    default: "'58'",
    description: 'Nilai inisialisasi menit awal yang aktif pada roda kanan (format 00 - 59).'
  },
  {
    name: '@activeTime',
    type: 'Event Payload ({ activeTime: String })',
    default: '-',
    description: 'Dipancarkan saat pengguna menggulir atau memilih kombinasi jam dan menit baru dengan payload objek `{ activeTime: "HH:mm" }`.'
  }
]
</script>
