<script setup>
/**
 * TrackingStatus.vue
 * Komponen timeline status / stepper vertikal enterprise PT Pegadaian
 * untuk memantau progres pengajuan pembiayaan, transaksi, dan verifikasi berkas.
 *
 * @prop {Array<Object>} items - Daftar tahapan status:
 *   [
 *     {
 *       id?: string | number,
 *       title: string,
 *       description?: string,
 *       timestamp?: string,
 *       status?: 'completed' | 'active' | 'in-progress' | 'pending' | 'inactive' | 'ditolak' | 'rejected'
 *     }
 *   ]
 * @prop {number} currentStep - Indeks langkah aktif (0-indexed). Digunakan otomatis
 *   menentukan status: indeks < currentStep (completed), indeks == currentStep (active),
 *   indeks > currentStep (pending) jika item tidak memiliki status eksplisit.
 * @prop {string} stepKey - Kunci unik untuk v-for :key (default: 'id')
 *
 * @slot item - Kustomisasi rendering keseluruhan item langkah { item, index, status, isLast }
 * @slot icon - Kustomisasi ikon indikator { item, index, status }
 * @slot title - Kustomisasi judul langkah { item, index, status }
 * @slot description - Kustomisasi deskripsi langkah { item, index, status }
 * @slot timestamp - Kustomisasi waktu/tanggal langkah { item, index, status }
 */
import { computed } from 'vue'

defineOptions({
  name: 'TrackingStatus'
})

const props = defineProps({
  items: {
    type: Array,
    default: () => []
  },
  currentStep: {
    type: Number,
    default: -1
  },
  stepKey: {
    type: String,
    default: 'id'
  }
})

/**
 * Menentukan apakah suatu langkah berstatus ditolak / rejected
 * @param {Object} item
 * @returns {boolean}
 */
const isRejected = (item) => {
  if (!item) return false
  if (item.isRejected === true) return true
  if (!item.status) return false
  const s = String(item.status).toLowerCase()
  return s === 'rejected' || s === 'ditolak' || s === 'reject' || s === 'error' || s === 'failed' || s === 'batal'
}

/**
 * Daftar tahapan yang dirender.
 * Jika terdapat langkah yang ditolak (rejected), langkah tersebut dijadikan end step (langkah terakhir)
 * dan seluruh sisa langkah berikutnya disembunyikan (di-hide).
 */
const displayedItems = computed(() => {
  if (!props.items || props.items.length === 0) return []
  const rejectedIndex = props.items.findIndex(isRejected)
  if (rejectedIndex !== -1) {
    return props.items.slice(0, rejectedIndex + 1)
  }
  return props.items
})

/**
 * Menentukan status komputasi per item berdasarkan prop status atau currentStep.
 * Tidak ada case berwarna merah; langkah ditolak yang menjadi end step memiliki styling aktif (highlight gelap).
 * @param {Object} item
 * @param {number} index
 * @returns {'completed' | 'active' | 'pending'}
 */
const resolveStatus = (item, index) => {
  if (item && item.status) {
    const s = String(item.status).toLowerCase()
    if (s === 'completed' || s === 'done' || s === 'success') return 'completed'
    if (s === 'active' || s === 'in-progress' || s === 'current') return 'active'
    if (isRejected(item)) return 'active'
    if (s === 'pending' || s === 'inactive' || s === 'waiting') return 'pending'
  }

  const rejectedIndex = props.items.findIndex(isRejected)
  if (rejectedIndex !== -1) {
    if (index < rejectedIndex) return 'completed'
    if (index === rejectedIndex) return 'active'
    return 'pending'
  }

  if (props.currentStep >= 0) {
    if (index < props.currentStep) return 'completed'
    if (index === props.currentStep) return 'active'
    return 'pending'
  }

  return 'pending'
}

/**
 * Menentukan apakah garis penghubung ke langkah berikutnya berstatus aktif (hijau)
 * @param {Object} item
 * @param {number} index
 * @returns {boolean}
 */
const isLineActive = (item, index) => {
  const currentStatus = resolveStatus(item, index)
  return currentStatus === 'completed' || currentStatus === 'active'
}

/**
 * Menghasilkan teks label status untuk keperluan aksesibilitas screen reader
 * @param {Object} item
 * @param {number} index
 * @returns {string}
 */
const getStatusA11yLabel = (item, index) => {
  if (isRejected(item)) return 'Ditolak'
  const status = resolveStatus(item, index)
  switch (status) {
    case 'completed':
      return 'Selesai'
    case 'active':
      return 'Sedang Berlangsung'
    default:
      return 'Menunggu'
  }
}

/**
 * Menentukan apakah suatu tahapan sedang aktif atau pernah aktif (completed)
 * @param {Object} item
 * @param {number} index
 * @returns {boolean}
 */
const isOrWasActive = (item, index) => {
  const status = resolveStatus(item, index)
  return status === 'completed' || status === 'active'
}

/**
 * Mendapatkan deskripsi langkah.
 * Wajib memiliki deskripsi jika tahapan aktif atau pernah aktif.
 * @param {Object} item
 * @param {number} index
 * @returns {string}
 */
const resolveDescription = (item, index) => {
  if (item && item.description) return item.description
  if (isOrWasActive(item, index)) {
    return 'Tahapan sedang dalam pemrosesan sistem operasional.'
  }
  return ''
}

/**
 * Mendapatkan timestamp langkah.
 * Wajib memiliki timestamp jika tahapan aktif atau pernah aktif.
 * @param {Object} item
 * @param {number} index
 * @returns {string}
 */
const resolveTimestamp = (item, index) => {
  if (item && item.timestamp) return item.timestamp
  if (isOrWasActive(item, index)) {
    return 'Waktu proses tercatat di sistem'
  }
  return ''
}
</script>

<template>
  <div class="tracking-status-wrapper">
    <ol class="tracking-status-list" role="list">
      <li
        v-for="(item, index) in displayedItems"
        :key="item[props.stepKey] || index"
        :class="[
          'tracking-status-item',
          `status-${resolveStatus(item, index)}`,
          {
            'is-last': index === displayedItems.length - 1,
            'is-rejected': isRejected(item),
            'has-description': isOrWasActive(item, index) && !!resolveDescription(item, index),
            'has-timestamp': isOrWasActive(item, index) && !!resolveTimestamp(item, index)
          }
        ]"
        :aria-current="resolveStatus(item, index) === 'active' ? 'step' : undefined"
      >
        <slot
          name="item"
          :item="item"
          :index="index"
          :status="resolveStatus(item, index)"
          :is-last="index === displayedItems.length - 1"
        >
          <!-- Kolom Indikator & Garis Vertikal -->
          <div class="tracking-indicator-col" aria-hidden="true">
            <div class="tracking-marker-container">
              <slot
                name="icon"
                :item="item"
                :index="index"
                :status="resolveStatus(item, index)"
              >
                <!-- Ikon Status Hijau Aktif / Selesai / Ditolak End Step (Ring Hijau #00AB4E) -->
                <svg
                  v-if="resolveStatus(item, index) === 'completed' || resolveStatus(item, index) === 'active'"
                  class="tracking-icon icon-active"
                  width="16"
                  height="16"
                  viewBox="0 0 16 16"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <circle
                    cx="8"
                    cy="8"
                    r="6.5"
                    stroke="#00AB4E"
                    stroke-width="3"
                    fill="#FFFFFF"
                  />
                </svg>

                <!-- Ikon Status Belum / Pending (Dot Solid Abu-Abu #939597) -->
                <svg
                  v-else
                  class="tracking-icon icon-pending"
                  width="16"
                  height="16"
                  viewBox="0 0 16 16"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <circle cx="8" cy="8" r="7" fill="#939597" />
                </svg>
              </slot>
            </div>

            <!-- Garis Penghubung Vertikal (Hanya muncul jika bukan item terakhir) -->
            <div
              v-if="index < displayedItems.length - 1"
              :class="[
                'tracking-line',
                isLineActive(item, index) ? 'line-active' : 'line-pending'
              ]"
            />
          </div>

          <!-- Kolom Konten Teks -->
          <div class="tracking-content-col">
            <span class="visually-hidden">
              ({{ getStatusA11yLabel(item, index) }})
            </span>

            <!-- Judul Langkah -->
            <div class="tracking-title">
              <slot
                name="title"
                :item="item"
                :index="index"
                :status="resolveStatus(item, index)"
              >
                {{ item.title }}
              </slot>
            </div>

            <!-- Deskripsi Langkah: Wajib tampil jika aktif atau pernah aktif -->
            <div
              v-if="isOrWasActive(item, index) && (resolveDescription(item, index) || $slots.description)"
              class="tracking-description"
            >
              <slot
                name="description"
                :item="item"
                :index="index"
                :status="resolveStatus(item, index)"
                :description="resolveDescription(item, index)"
              >
                {{ resolveDescription(item, index) }}
              </slot>
            </div>

            <!-- Tanggal / Waktu Langkah: Wajib tampil jika aktif atau pernah aktif -->
            <div
              v-if="isOrWasActive(item, index) && (resolveTimestamp(item, index) || $slots.timestamp)"
              class="tracking-timestamp"
            >
              <slot
                name="timestamp"
                :item="item"
                :index="index"
                :status="resolveStatus(item, index)"
                :timestamp="resolveTimestamp(item, index)"
              >
                {{ resolveTimestamp(item, index) }}
              </slot>
            </div>
          </div>
        </slot>
      </li>
    </ol>
  </div>
</template>

<style lang="scss">
