    // Indikator Vertikal & Garis
    .tracking-indicator-col {
      display: flex;
      flex-direction: column;
      align-items: center;
      width: 16px;
      margin-right: 12px;
      flex-shrink: 0;
      position: relative;
    }

    .tracking-marker-container {
      width: 16px;
      height: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      position: relative;
      z-index: 2;
    }

    .tracking-icon {
      width: 16px;
      height: 16px;
      display: block;
      flex-shrink: 0;
    }

    // Garis penghubung vertikal: Dari titik tengah lingkaran item saat ini (top: 12px)
    // tembus tepat ke titik tengah lingkaran item berikutnya (bottom: -12px)
    .tracking-line {
