<script setup>
defineOptions({
  name: 'AddAmountDenomSection'
})

import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import AddAmountDenom from '@/components/AddAmount/AddAmountDenom.vue'
import Button from '@/components/Button/Button.vue'

const activeVariant = ref('eform')
const syncStatus = ref('Kalkulasi real-time siap diverifikasi')

const defaultData = [
  { id: 1, denom: 'Pecahan 1 Gram', grams: 1, priceNum: 1350000, price: 'Rp 1.350.000', value: 0 },
  { id: 2, denom: 'Pecahan 2 Gram', grams: 2, priceNum: 2680000, price: 'Rp 2.680.000', value: 0 },
  { id: 3, denom: 'Pecahan 5 Gram', grams: 5, priceNum: 6650000, price: 'Rp 6.650.000', value: 0 },
  { id: 4, denom: 'Pecahan 10 Gram', grams: 10, priceNum: 13200000, price: 'Rp 13.200.000', value: 0 },
  { id: 5, denom: 'Pecahan 25 Gram', grams: 25, priceNum: 32800000, price: 'Rp 32.800.000', value: 0 }
]

const denomItems = ref(JSON.parse(JSON.stringify(defaultData)))

const totalPieces = computed(() => {
  return denomItems.value.reduce((sum, item) => sum + (item.value || 0), 0)
})

const totalGrams = computed(() => {
  return denomItems.value.reduce((sum, item) => sum + ((item.value || 0) * (item.grams || 1)), 0)
})

const totalPrice = computed(() => {
  return denomItems.value.reduce((sum, item) => sum + ((item.value || 0) * (item.priceNum || 0)), 0)
})

const formatNumber = (num) => {
  return new Intl.NumberFormat('id-ID').format(num)
}

const resetScenario = () => {
  denomItems.value = JSON.parse(JSON.stringify(defaultData))
  syncStatus.value = 'Data pilihan direset ke status awal'
}

const loadScenario = () => {
  denomItems.value = [
    { id: 1, denom: 'Pecahan 1 Gram', grams: 1, priceNum: 1350000, price: 'Rp 1.350.000', value: 2 },
    { id: 2, denom: 'Pecahan 2 Gram', grams: 2, priceNum: 2680000, price: 'Rp 2.680.000', value: 1 },
    { id: 3, denom: 'Pecahan 5 Gram', grams: 5, priceNum: 6650000, price: 'Rp 6.650.000', value: 1 },
    { id: 4, denom: 'Pecahan 10 Gram', grams: 10, priceNum: 13200000, price: 'Rp 13.200.000', value: 0 },
    { id: 5, denom: 'Pecahan 25 Gram', grams: 25, priceNum: 32800000, price: 'Rp 32.800.000', value: 0 }
  ]
