  { id: 402, denom: 'Keping 2 Gram Logam Mulia', price: 'Rp 2.680.000', value: 0 }
])

const addAmountDenomProps = [
  {
    name: 'modelValue',
    type: 'Array<{ id, denom, price, value, disabled?, iconCustom? }>',
    default: '() => []',
    isModel: true,
    description: 'Array objek denominasi emas yang diikat dua arah. Setiap item memuat nilai kuantitas saat ini.'
  },
  {
    name: 'variant',
    type: "'default' | 'eform'",
    default: "'default'",
    description: "Varian tata letak: 'eform' untuk grid kartu mandiri berbingkai, atau 'default' untuk baris vertikal kasir loket."
  },
  {
    name: 'class',
    type: 'String',
    default: "''",
    description: 'Kelas CSS tambahan yang disuntikkan ke wrapper masing-masing kartu denominasi.'
  },
