<template>
  <ModalBottomSheet
    v-model="isOpen"
    :title="props.title"
    :size="props.size"
    :mode="props.mode"
    :persistent="props.persistent"
    :close-on-overlay="props.closeOnOverlay"
    :show-close-button="props.showCloseButton"
    :show-grabber="props.showGrabber"
    class="product-selection-modal"
    @hide="onHide"
  >
    <template #body="{ close }">
      <div class="product-selection-content d-flex flex-column gap-3">
        <!-- Alert Infotips Banner (Reused from AlertVarian.vue) -->
        <div v-if="props.alertMessage" class="product-alert-wrapper">
          <AlertVarian
            color="info"
            variant="aksen"
            :label="props.alertMessage"
            :hide-action="true"
          />
        </div>

        <!-- Product Option Cards List -->
        <div class="product-options-list d-flex flex-column gap-3" role="radiogroup" :aria-label="props.title">
          <button
            v-for="product in productList"
            :key="product.id"
            type="button"
            role="radio"
            :aria-checked="selectedId === product.id"
            class="product-option-card w-100 text-start"
            :class="{ 'is-selected': selectedId === product.id, 'is-disabled': product.disabled }"
            :disabled="product.disabled"
            @click="selectProduct(product)"
          >
            <!-- Content Left: Title and Subtitle -->
            <div class="product-card-text">
              <div class="product-card-title">{{ product.title }}</div>
              <div class="product-card-desc">{{ product.description }}</div>
            </div>

            <!-- Content Right: Illustrative Icon Badge -->
            <div class="product-card-icon-wrap" aria-hidden="true">
