              <!-- Custom Slot Icon -->
              <template v-else>
                <span v-if="product.icon" v-html="product.icon"></span>
                <span v-else class="text-secondary fw-bold">#</span>
              </template>
            </div>
          </button>
          <!-- Actions Button Group (Bisa dikustomisasi via slot #actions) -->
          <slot
            name="actions"
            :close="close"
            :selected="selectedId"
            :submit="() => handleSubmit(close)"
            :cancel="() => handleCancel(close)"
          >
            <div class="d-flex flex-column gap-2 w-100">
              <!-- Action Kembali (Reused Button type="neutral" / outline) -->
              <Button
                type="neutral"
                size="lg"
                :label="props.cancelText"
                class="w-100"
                @click="handleCancel(close)"
              />

              <!-- Action Lanjutkan Pengajuan (Reused Button type="primary") -->
              <Button
                type="primary"
                size="lg"
                :label="props.confirmText"
                :disabled="!selectedId"
                class="w-100"
                @click="handleSubmit(close)"
              />
            </div>
          </slot>
        </div>
      </div>
    </template>

    <!-- Slot Footer Terpisah (Opsional, aktif jika template #footer disediakan consumer) -->
    <template #footer="{ close }" v-if="$slots.footer">
      <slot
        name="footer"
        :close="close"
        :selected="selectedId"
        :submit="() => handleSubmit(close)"
        :cancel="() => handleCancel(close)"
      />
    </template>
  </ModalBottomSheet>
</template>

<script setup>
