 * yang diadaptasi secara presisi 1:1 dari desain Figma (Node 2415:24648).
 * Mengintegrasikan ModalBottomSheet adaptif (Desktop Modal ↔ Mobile BottomSheet),
 * AlertVarian aksen biru, Button Pegadaian (Button.vue), dan kartu seleksi opsi produk pinjaman Kresna & Arrum Syariah.
 * 
 * @prop {boolean} modelValue - Visibilitas dialog (v-model)
 * @prop {string} [selected] - ID produk yang terpilih (v-model:selected)
 * @prop {string} [title='Pilih Produk Pengajuan'] - Judul dialog modal
 * @prop {string} [alertMessage] - Teks pesan tips panduan
 * @prop {Array} [products] - Daftar produk pilihan kustom
 * @prop {string} [cancelText='Kembali'] - Label tombol kembali
 * @prop {string} [confirmText='Lanjutkan Pengajuan'] - Label tombol konfirmasi
 * @prop {'auto' | 'modal' | 'bottom-sheet'} [mode='auto'] - Mode tampilan dialog
 * @prop {boolean} [persistent=false] - Mencegah dialog ditutup via backdrop / ESC
 * @prop {boolean} [closeOnOverlay=true] - Menutup modal saat area overlay/backdrop luar diklik
 * @prop {boolean} [showCloseButton=false] - Menampilkan tombol silang tutup
 * @prop {boolean} [showGrabber=true] - Menampilkan grabber pill bar saat di mobile bottom-sheet
 * 
 * @slot header - Kustomisasi seluruh area bar header modal/bottom sheet (scoped { close })
 * @slot alert - Kustomisasi area banner tips panduan di atas opsi produk
 * @slot actions - Kustomisasi tombol aksi Kembali & Lanjutkan di dalam body (scoped { close, selected, submit, cancel })
 * @slot footer - Bar footer terpisah di luar area body jika diperlukan (scoped { close, selected, submit, cancel })
 * @slot body - Kustomisasi seluruh konten isi dialog modal (scoped { close })
 * 
 * @emits update:modelValue - Mengubah state visibilitas dialog
 * @emits update:selected - Mengubah ID produk terpilih
 * @emits submit - Dipancarkan saat tombol konfirmasi diklik dengan payload objek produk terpilih
 * @emits cancel - Dipancarkan saat tombol kembali atau overlay backdrop diklik
 * @emits change - Dipancarkan saat pilihan kartu opsi produk berganti
 * @emits hide - Dipancarkan saat dialog modal mulai menutup
 */
import { ref, watch, computed } from 'vue'
import ModalBottomSheet from './ModalBottomSheet.vue'
import AlertVarian from '@/components/Alert/AlertVarian.vue'
import Button from '@/components/Button/Button.vue'

defineOptions({
  name: 'ProductSelectionModal'
})

const props = defineProps({
  title: {
    type: String,
    default: 'Pilih Produk Pengajuan'
  },
  alertMessage: {
    type: String,
    default: 'Kedua produk merupakan pinjaman karyawan. Pilih salah satu berdasarkan preferensi Anda.'
  },
  products: {
    type: Array,
    default: () => [
      {
        id: 'kresna',
        type: 'kresna',
        title: 'Pegadaian Kresna',
        description: 'Fasilitas pinjaman bagi karyawan dengan jaminan payroll.'
      },
      {
        id: 'arrum',
        type: 'arrum',
        title: 'Arrum Multiguna Internal',
        description: 'Fasilitas pinjaman bagi karyawan dengan jaminan SK Karyawan berdasarkan prinsip syariah.'
      }
    ]
  },
  selected: {
    type: String,
    default: ''
  },
  cancelText: {
    type: String,
    default: 'Kembali'
  },
  confirmText: {
    type: String,
    default: 'Lanjutkan Pengajuan'
  },
  size: {
    type: String,
    default: 'sm'
  },
  mode: {
    type: String,
    default: 'auto'
  },
  persistent: {
    type: Boolean,
    default: false
  },
  closeOnOverlay: {
    type: Boolean,
    default: true
  },
  showCloseButton: {
    type: Boolean,
    default: false
  },
  showGrabber: {
    type: Boolean,
    default: true
  }
})

const emit = defineEmits(['update:modelValue', 'update:selected', 'submit', 'cancel', 'change', 'hide'])

const isOpen = defineModel({ default: false })
const selectedId = ref(props.selected || '')

watch(
  () => props.selected,
  (newVal) => {
    selectedId.value = newVal || ''
  }
)

const productList = computed(() => props.products)

const selectProduct = (product) => {
  if (product.disabled) return
  selectedId.value = product.id
  emit('update:selected', product.id)
  emit('change', product)
}

const handleCancel = (close) => {
  emit('cancel')
  if (typeof close === 'function') close()
  else isOpen.value = false
}

const handleSubmit = (close) => {
  const chosen = productList.value.find((p) => p.id === selectedId.value)
  emit('submit', chosen || { id: selectedId.value })
  if (typeof close === 'function') close()
  else isOpen.value = false
}

const onHide = (event) => {
  emit('hide', event)
  if (event?.trigger === 'backdrop') {
    emit('cancel')
  }
}
</script>

