  { id: 'logam_mulia', label: 'Logam Mulia Batangan (Antam, UBS, Galeri 24)', estPlafon: 30000000 },
  { id: 'bpkb_motor', label: 'BPKB Sepeda Motor (Honda, Yamaha, Suzuki)', estPlafon: 12000000 },
  { id: 'bpkb_mobil', label: 'BPKB Mobil Pribadi / Niaga', estPlafon: 75000000 },
  { id: 'elektronik_gadget', label: 'Gadget & Handphone Flagship', estPlafon: 5000000 },
  { id: 'laptop_kamera', label: 'Laptop & Peralatan Kamera Profesional', estPlafon: 8000000 }
]

function formatRupiah(num) {
  return 'Rp ' + Number(num || 0).toLocaleString('id-ID')
}

const estimatedPlafonTotal = computed(() => {
  return scenarioAgunan.value.reduce((acc, currentId) => {
    const item = kategoriAgunanOptions.find(k => k.id === currentId)
    return acc + (item ? item.estPlafon : 0)
  }, 0)
})

function resetScenarioData() {
  scenarioAgunan.value = []
}

function loadScenarioData() {
  scenarioAgunan.value = ['perhiasan_emas', 'logam_mulia', 'bpkb_motor']
}

