<script setup>
import { ref } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import InputWithActionButton from '@/components/Input/InputWithActionButton.vue'
import InputText from '@/components/Input/InputText.vue'

// Real-world scenario state
const rcNoRekening = ref('034101000123502')
const bankStatus = ref('Rekening Sah & Terverifikasi')
const selectedBankName = ref('BRI (Bank Rakyat Indonesia)')
const bankOwner = ref('BUDI SANTOSO')
const isBankValid = ref(true)
const isValidating = ref(false)

function handleValidateBank() {
  if (!rcNoRekening.value || rcNoRekening.value.length < 8) {
    bankStatus.value = 'Gagal: Nomor Rekening Tidak Valid'
    bankOwner.value = 'Data rekening tidak ditemukan pada sistem perbankan'
    isBankValid.value = false
    return
  }

  isValidating.value = true
  setTimeout(() => {
    isValidating.value = false
    bankStatus.value = 'Rekening Sah & Terverifikasi'
    isBankValid.value = true
  }, 400)
}

function resetScenarioData() {
  rcNoRekening.value = ''
  bankStatus.value = 'Menunggu Input Nomor Rekening'
  selectedBankName.value = 'Pilih Bank'
  bankOwner.value = ''
  isBankValid.value = false
}

function loadScenarioData() {
  setPreset('034101000123502', 'BRI (Bank Rakyat Indonesia)', 'BUDI SANTOSO')
}

function setPreset(norek, bank, nama) {
  rcNoRekening.value = norek
  selectedBankName.value = bank
  bankOwner.value = nama
  isBankValid.value = true
  bankStatus.value = 'Rekening Sah & Terverifikasi'
}

// Lifecycle states
const stateDefault = ref('')
function handleCheckDefault() {
  if (stateDefault.value) {
    alert(`Mencari berkas dokumen: ${stateDefault.value}`)
  }
}

const statePromo = ref('BERKAH10')
function handleApplyPromo() {
  if (statePromo.value) {
    alert(`Kupon diskon "${statePromo.value}" berhasil diterapkan!`)
  }
}

// Props Matrix Documentation
const actionButtonProps = [
  {
    name: 'buttonTitle',
    type: 'String',
    default: "'Button'",
    description: 'Teks label yang ditampilkan pada tombol aksi di sisi kanan input.'
  },
  {
    name: '#input',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot utama tempat menyisipkan komponen kontrol input (InputText, InputNominal, dsb).'
  },
  {
    name: '@click',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Event yang dipancarkan saat pengguna mengklik tombol aksi.'
  }
]
</script>
