<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import CalendarDropdown from '@/components/Input/CalendarDropdown.vue'

// Real-world scenario state
const rcTanggalAkad = ref('2026-09-02')
const selectedTenor = ref(120)

const tenorOptions = [
  { label: '30 Hari (Cepat)', days: 30 },
  { label: '60 Hari', days: 60 },
  { label: '120 Hari (Standar KCA)', days: 120 },
  { label: '150 Hari (Perpanjangan)', days: 150 }
]

function addDaysToDate(dateStr, days) {
  if (!dateStr) return null
  const date = new Date(dateStr)
  if (isNaN(date.getTime())) return null
  date.setDate(date.getDate() + days)
  return date
}

function formatDateIndo(dateObj) {
  if (!dateObj) return 'Belum ditentukan'
  return new Intl.DateTimeFormat('id-ID', {
    day: 'numeric',
    month: 'long',
    year: 'numeric'
  }).format(dateObj)
}

const formattedAkadDate = computed(() => {
  if (!rcTanggalAkad.value) return 'Belum dipilih'
  const d = new Date(rcTanggalAkad.value)
  return isNaN(d.getTime()) ? '-' : formatDateIndo(d)
})

const formattedDueDate = computed(() => {
  const d = addDaysToDate(rcTanggalAkad.value, selectedTenor.value)
  return formatDateIndo(d)
})

const formattedGracePeriodDate = computed(() => {
  const d = addDaysToDate(rcTanggalAkad.value, selectedTenor.value + 15)
  return formatDateIndo(d)
})

const formattedAuctionDate = computed(() => {
  const d = addDaysToDate(rcTanggalAkad.value, selectedTenor.value + 25)
  return formatDateIndo(d)
})

function resetScenarioData() {
  rcTanggalAkad.value = ''
  selectedTenor.value = 120
}

function loadScenarioData() {
  rcTanggalAkad.value = '2026-09-15'
  selectedTenor.value = 120
}

// Lifecycle states
const stateDefault = ref('')
const statePreselected = ref('2026-09-15')
const stateDisabled = ref('2026-01-10')
const stateLimited = ref('2026-09-20')

// Props Matrix Documentation
const calendarDropdownProps = [
  {
    name: 'modelValue',
    type: 'String',
    default: "''",
    description: 'Nilai tanggal yang terpilih (two-way binding via v-model). Format standar: YYYY-MM-DD.'
  },
  {
    name: 'title',
    type: 'String',
    default: "'Tanggal Lahir'",
    description: 'Label teks judul yang ditampilkan di atas kolom input dropdown kalender.'
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "''",
    description: 'Teks instruksi placeholder sebelum pengguna menentukan pilihan tanggal.'
  },
  {
    name: 'minDate',
    type: 'String',
    default: 'null',
    description: 'Batas tanggal paling awal yang diizinkan untuk dipilih (format: YYYY-MM-DD).'
  },
  {
    name: 'maxDate',
    type: 'String',
    default: 'null',
    description: 'Batas tanggal paling akhir yang diizinkan untuk dipilih (format: YYYY-MM-DD).'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi kalender dan menerapkan tampilan visual teredam.'
  },
  {
    name: 'flexWidth',
    type: 'Boolean',
    default: 'false',
    description: 'Mengatur lebar input 50% untuk integrasi rentang tanggal berdampingan di DateRangePicker.'
  },
  {
    name: 'alignment',
    type: 'String',
    default: "'start'",
    description: "Penjajaran posisi pop-up kalender terhadap input ('start' atau 'end')."
  }
]
</script>
