            aria-hidden="true"
            @click="closePalette"
          ></div>

          <!-- Centered Spotlight Dialog Card -->
          <div class="spotlight-modal-card shadow-2xl">
            <!-- Modal Search Input Header -->
            <div class="spotlight-input-bar d-flex align-items-center px-3 py-3 border-bottom">
