                @keydown="handleKeydown"
              />

              <button
                v-if="searchQuery"
                type="button"
                class="btn-clear-modal-search me-2"
                title="Hapus kata kunci"
                aria-label="Hapus kata kunci"
                @click="clearSearch"
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                  <line x1="18" y1="6" x2="6" y2="18"></line>
                  <line x1="6" y1="6" x2="18" y2="18"></line>
                </svg>
              </button>

              <button
                type="button"
                class="btn-esc-keycap"
                title="Tutup pencarian (Esc)"
                @click="closePalette"
              >
                ESC
              </button>
            </div>

            <!-- Category Quick Filter Chips -->
            <div class="spotlight-filter-bar d-flex align-items-center gap-1 px-3 py-2 border-bottom bg-light">
              <span class="filter-label text-uppercase text-muted me-1">Filter:</span>
              <div class="filter-chips-track d-flex align-items-center gap-1 overflow-auto">
                <button
                  type="button"
                  class="filter-chip-btn"
                  :class="{ 'is-active': selectedCategory === 'all' }"
                  @click="setCategory('all')"
                >
                  <span>Semua</span>
                  <span class="chip-count">{{ totalComponents }}</span>
                </button>
                <button
                  v-for="cat in categories"
                  :key="cat.id"
                  type="button"
                  class="filter-chip-btn"
                  :class="{ 'is-active': selectedCategory === cat.id }"
                  @click="setCategory(cat.id)"
                >
                  <span>{{ cat.shortName }}</span>
                  <span class="chip-count">{{ cat.components.length }}</span>
                </button>
              </div>
            </div>

            <!-- Search Result Items List -->
            <div ref="resultsListRef" class="spotlight-results-scroll p-2">
              <template v-if="filteredItems.length > 0">
                <div
                  v-for="(item, idx) in filteredItems"
                  :key="item.id"
                  :id="`spotlight-item-${item.id}`"
                  class="spotlight-result-row d-flex align-items-center justify-content-between px-3 py-2.5 rounded-3"
                  :class="{ 'is-selected': selectedIndex === idx }"
                  @click="selectItem(item.id)"
                  @mouseenter="selectedIndex = idx"
                >
                  <div class="result-item-main d-flex align-items-center min-w-0 flex-grow-1">
                    <!-- Category Icon Badge -->
                    <div class="result-icon-box" :class="{ 'is-selected': selectedIndex === idx }">
                      <component :is="getCategoryIconSvg(item.categoryIcon)" />
                    </div>

                    <div class="result-text-box min-w-0 flex-grow-1">
                      <div class="d-flex align-items-center gap-2">
                        <span class="result-title fw-bold text-truncate">{{ item.label }}</span>
                        <span class="badge rounded-pill result-category-badge ms-2">{{ item.categoryName }}</span>
                      </div>
                      <p class="result-desc small text-muted text-truncate mb-0">
                        {{ item.description || item.useCase || item.categoryFullName }}
                      </p>
                    </div>
                  </div>

                  <!-- Right Action Keycap Hint -->
                  <div class="result-action-hint d-flex align-items-center gap-1 flex-shrink-0 ms-2">
                    <span v-if="selectedIndex === idx" class="badge-select-enter d-inline-flex align-items-center gap-1">
                      <span>Buka</span>
                      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                        <polyline points="9 10 4 15 9 20"></polyline>
                        <path d="M20 4v7a4 4 0 0 1-4 4H4"></path>
                      </svg>
                    </span>
                    <svg v-else width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#cbd5e1" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="enter-icon-idle">
                      <polyline points="9 10 4 15 9 20"></polyline>
                      <path d="M20 4v7a4 4 0 0 1-4 4H4"></path>
                    </svg>
                  </div>
                </div>
              </template>

              <!-- Empty State -->
              <div v-else class="spotlight-empty-state py-5 px-3 text-center">
                <div class="empty-icon-circle mb-3 mx-auto">
                  <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <circle cx="11" cy="11" r="8"></circle>
                    <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
                    <line x1="8" y1="11" x2="14" y2="11"></line>
                  </svg>
                </div>
                <h6 class="fw-bold text-dark mb-1">
                  Komponen "{{ searchQuery }}" tidak ditemukan
                </h6>
                <p class="small text-muted mb-3">
                  Coba kata kunci lain atau klik rekomendasi komponen di bawah:
                </p>
                <div class="d-flex flex-wrap justify-content-center gap-1.5">
                  <button
                    v-for="sugg in searchSuggestions"
                    :key="sugg"
                    type="button"
                    class="btn btn-sm btn-outline-secondary suggestion-chip"
                    @click="applySuggestion(sugg)"
                  >
                    {{ sugg }}
                  </button>
                </div>
              </div>
            </div>

            <!-- Command Palette Footer -->
            <div class="spotlight-footer d-flex align-items-center justify-content-between px-3 py-2 bg-light border-top small text-muted">
              <div class="d-flex align-items-center gap-1.5">
                <span class="footer-live-dot" aria-hidden="true"></span>
                <span>Ditemukan <strong class="text-dark">{{ filteredItems.length }}</strong> komponen</span>
              </div>
              <div class="d-flex align-items-center gap-2 keyboard-hints">
                <span class="d-none d-sm-inline-flex align-items-center gap-1">
                  <kbd class="key-tag">↑</kbd>
                  <kbd class="key-tag">↓</kbd>
                  <span>navigasi</span>
                </span>
                <span class="d-none d-sm-inline-flex align-items-center gap-1">
                  <kbd class="key-tag">↵</kbd>
                  <span>pilih</span>
                </span>
                <span class="d-inline-flex align-items-center gap-1">
                  <kbd class="key-tag">esc</kbd>
                  <span>tutup</span>
                </span>
              </div>
