          </div>
        </div>
      </Transition>
    </Teleport>
  </header>
</template>

<script setup>
/**
 * @file PlaygroundHeader.vue
 * @description Enterprise obsidian glassmorphic header with teleported Spotlight Command Palette (⌘K),
 * category filter chips, keyboard arrow navigation, and live component status.
 */
import { ref, computed, onMounted, onUnmounted, nextTick, h } from 'vue'

const props = defineProps({
  totalComponents: {
    type: Number,
    default: 81
  },
  categories: {
    type: Array,
    default: () => []
  },
  allComponents: {
    type: Array,
    default: () => []
  }
})

const emit = defineEmits(['navigate', 'navigate-category'])

const searchQuery = ref('')
const isOpen = ref(false)
const selectedCategory = ref('all')
const selectedIndex = ref(0)
const modalInputRef = ref(null)
const resultsListRef = ref(null)

const searchSuggestions = ['InputText', 'DataTable', 'LineChart', 'Stepper', 'DatePicker', 'InputKtp', 'CustomModal', 'RadioComponent']

// Filtered items based on active category filter and query
const filteredItems = computed(() => {
  const q = searchQuery.value.trim().toLowerCase()
  return props.allComponents.filter((item) => {
    const matchCategory = selectedCategory.value === 'all' || item.categoryId === selectedCategory.value
    if (!matchCategory) return false
    if (!q) return true
    return (
      item.label.toLowerCase().includes(q) ||
      item.categoryName.toLowerCase().includes(q) ||
      (item.categoryFullName && item.categoryFullName.toLowerCase().includes(q)) ||
      (item.description && item.description.toLowerCase().includes(q)) ||
      (item.useCase && item.useCase.toLowerCase().includes(q))
    )
  })
})

const openPalette = () => {
  isOpen.value = true
  selectedIndex.value = 0
  nextTick(() => {
    modalInputRef.value?.focus()
  })
}

const closePalette = () => {
  isOpen.value = false
}

const clearSearch = () => {
  searchQuery.value = ''
  selectedIndex.value = 0
  nextTick(() => {
    modalInputRef.value?.focus()
  })
}

const setCategory = (catId) => {
  selectedCategory.value = catId
  selectedIndex.value = 0
  nextTick(() => {
    modalInputRef.value?.focus()
  })
}

const applySuggestion = (text) => {
  searchQuery.value = text
  selectedIndex.value = 0
  nextTick(() => {
    modalInputRef.value?.focus()
  })
}

const selectItem = (id) => {
  emit('navigate', id)
  closePalette()
  searchQuery.value = ''
  selectedCategory.value = 'all'
}

const handleKeydown = (e) => {
  if (filteredItems.value.length === 0) {
    if (e.key === 'Escape') {
      closePalette()
    }
    return
  }

  if (e.key === 'ArrowDown') {
    e.preventDefault()
    selectedIndex.value = (selectedIndex.value + 1) % filteredItems.value.length
    scrollSelectedItemIntoView()
  } else if (e.key === 'ArrowUp') {
    e.preventDefault()
    selectedIndex.value = (selectedIndex.value - 1 + filteredItems.value.length) % filteredItems.value.length
    scrollSelectedItemIntoView()
  } else if (e.key === 'Enter') {
    e.preventDefault()
    const item = filteredItems.value[selectedIndex.value]
    if (item) {
      selectItem(item.id)
    }
  } else if (e.key === 'Escape') {
    e.preventDefault()
    closePalette()
  }
}

const scrollSelectedItemIntoView = () => {
  const item = filteredItems.value[selectedIndex.value]
  if (item) {
    const el = document.getElementById(`spotlight-item-${item.id}`)
    if (el) {
      el.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
    }
  }
}

const handleGlobalKeydown = (e) => {
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
    e.preventDefault()
    if (isOpen.value) {
      closePalette()
    } else {
      openPalette()
    }
  }
}

onMounted(() => {
  window.addEventListener('keydown', handleGlobalKeydown)
})

onUnmounted(() => {
  window.removeEventListener('keydown', handleGlobalKeydown)
})

// Clean inline SVG category icons (Zero arbitrary npm dependencies)
function getCategoryIconSvg(iconType) {
  switch (iconType) {
    case 'text':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('polyline', { points: '4 7 4 4 20 4 20 7' }),
        h('line', { x1: 9, y1: 20, x2: 15, y2: 20 }),
        h('line', { x1: 12, y1: 4, x2: 12, y2: 20 })
      ])
    case 'choice':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('rect', { x: 3, y: 3, width: 18, height: 18, rx: 4 }),
        h('polyline', { points: '9 12 11 14 15 10' })
      ])
    case 'date':
    case 'datetime':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('rect', { x: 3, y: 4, width: 18, height: 18, rx: 2 }),
        h('line', { x1: 16, y1: 2, x2: 16, y2: 6 }),
        h('line', { x1: 8, y1: 2, x2: 8, y2: 6 }),
        h('line', { x1: 3, y1: 10, x2: 21, y2: 10 })
      ])
    case 'search':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('circle', { cx: 11, cy: 11, r: 8 }),
        h('line', { x1: 21, y1: 21, x2: 16.65, y2: 16.65 })
      ])
    case 'media':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('path', { d: 'M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z' }),
        h('circle', { cx: 12, cy: 13, r: 4 })
      ])
    case 'button':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('rect', { x: 2, y: 6, width: 20, height: 12, rx: 6 }),
        h('circle', { cx: 8, cy: 12, r: 2 })
      ])
    case 'feedback':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('path', { d: 'M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9' }),
        h('path', { d: 'M13.73 21a2 2 0 0 1-3.46 0' })
      ])
    case 'data':
    case 'table':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('rect', { x: 3, y: 3, width: 18, height: 18, rx: 2 }),
        h('path', { d: 'M3 9h18M3 15h18M9 3v18' })
      ])
    case 'chart':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('line', { x1: 18, y1: 20, x2: 18, y2: 10 }),
        h('line', { x1: 12, y1: 20, x2: 12, y2: 4 }),
        h('line', { x1: 6, y1: 20, x2: 6, y2: 14 })
      ])
    case 'stepper':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('circle', { cx: 12, cy: 5, r: 3 }),
        h('line', { x1: 12, y1: 8, x2: 12, y2: 13 }),
        h('circle', { cx: 12, cy: 16, r: 3 })
      ])
    case 'utility':
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('circle', { cx: 12, cy: 12, r: 3 }),
        h('path', { d: 'M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z' })
      ])
    case 'nav':
    default:
      return h('svg', { width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinecap: 'round', strokeLinejoin: 'round' }, [
        h('rect', { x: 3, y: 3, width: 18, height: 18, rx: 2 }),
        h('line', { x1: 9, y1: 3, x2: 9, y2: 21 }),
        h('line', { x1: 9, y1: 9, x2: 21, y2: 9 })
      ])
  }
}
</script>

<style scoped>
/* ── Obsidian Header Shell ───────────────────────────────────────── */
.playground-header {
  background-color: #0b130e;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(16px);
