<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import InputTextArea from '@/components/Input/InputTextArea.vue'

// Real-world scenario state
const rcKeteranganAgunan = ref('Cincin emas permata berlian 0.25ct, lingkar 16mm, emas putih 17 Karat, kondisi mulus tanpa cacat fisik.')

function resetScenarioData() {
  rcKeteranganAgunan.value = ''
}

function loadScenarioData() {
  rcKeteranganAgunan.value = 'Kalung emas kuning model rantai, karatase 18K (750), berat kotor 14.80 gr, pengait utuh, siap taksir.'
}

function setPreset(text) {
  rcKeteranganAgunan.value = text
}

// Appraisal Defect Analysis Engine
const defectAnalysis = computed(() => {
  const desc = String(rcKeteranganAgunan.value || '').toLowerCase()

  if (!desc.trim()) {
    return {
      isAcceptable: false,
      isDamaged: false,
      statusGrade: 'Menunggu Input',
      condition: 'Belum Ada Catatan',
      deduction: '0%',
      message: 'Masukkan deskripsi hasil uji fisik barang agunan'
    }
  }

  const isDamaged = desc.includes('patah') || desc.includes('rusak') || desc.includes('cacat') || desc.includes('penyok')
  const isScratched = desc.includes('gores') || desc.includes('lecet') || desc.includes('kusam')

  let statusGrade = 'Grade A (Prima)'
  let condition = 'Sempurna & Mulus'
  let deduction = 'Tanpa Potongan (100% SPE)'

  if (isDamaged) {
    statusGrade = 'Grade C (Perlu Reparasi)'
    condition = 'Kerusakan Fisik Terdeteksi'
    deduction = 'Potongan Biaya Reparasi 5%'
  } else if (isScratched) {
    statusGrade = 'Grade B (Cacat Ringan)'
    condition = 'Goresan Pemakaian Wajar'
    deduction = 'Potongan Biaya Cuci Emas 1%'
  }

  return {
    isAcceptable: true,
    isDamaged,
    statusGrade,
    condition,
    deduction,
    message: 'Catatan kondisi agunan telah diarsipkan secara permanen pada Surat Bukti Gadai'
  }
})

// Lifecycle states
const stateDefault = ref('')
const stateCount = ref('Mengajukan perpanjangan jangka waktu sewa modal selama 30 hari karena menunggu pencairan termin usaha.')
const stateUpper = ref('JL. KRAMAT RAYA NO. 162, KEL. KENARI, KEC. SENEN, JAKARTA PUSAT')
const stateError = ref('')

// Props Matrix Documentation
const textAreaProps = [
  {
    name: 'modelValue',
    type: 'String',
    default: "''",
    description: 'Nilai teks multi-baris yang diikat secara dua arah via v-model.'
  },
  {
    name: 'label',
    type: 'String',
    default: "''",
    description: 'Teks judul label formal di atas area input.'
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "''",
    description: 'Teks petunjuk saat area masukan teks masih kosong.'
  },
  {
    name: 'variant',
    type: "'default' | 'count' | 'uppercase'",
    default: "'default'",
    description: 'Mode tampilan: counter kuota karakter (count) atau huruf kapital otomatis (uppercase).'
  },
  {
    name: 'maxLength',
    type: 'Number',
    default: 'null',
    description: 'Batas kuota karakter maksimal saat mengaktifkan variant="count".'
  },
  {
    name: 'error',
    type: 'String',
    default: "''",
    description: 'Pesan kesalahan validasi di bawah area teks yang memicu border merah.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan pengeditan teks dan memberi gaya visual redup (muted).'
  },
  {
    name: '@update:modelValue',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Event reaktif yang dipancarkan saat teks diubah (sinkronisasi v-model).'
  }
]
</script>
