const getCategory = (catId) => {
  return categories.find(c => c.id === catId) || {}
}

const scrollToTopNav = () => {
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

const activeCategoryId = ref('category-1')
const topNavRef = ref(null)

const scrollActiveTabIntoView = (catId) => {
  topNavRef.value?.scrollNavPillIntoView(catId)
}

const totalComponents = computed(() => {
  return categories.reduce((sum, cat) => sum + cat.components.length, 0)
})

const allComponents = computed(() => {
  const list = []
  categories.forEach(cat => {
    cat.components.forEach(comp => {
      list.push({
        ...comp,
        categoryId: cat.id,
        categoryName: cat.shortName,
        categoryFullName: cat.name,
        categoryIcon: cat.icon,
        description: cat.description,
        useCase: cat.useCase
      })
    })
  })
  return list
})

const isManualNav = ref(false)

const scrollToTargetElement = (el, yOffset = -112) => {
  if (!el) return
  const currentY = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0
  const targetY = Math.max(0, currentY + el.getBoundingClientRect().top + yOffset)
  window.scrollTo({ top: targetY, behavior: 'smooth' })
  if (document.body && document.body.scrollHeight > document.body.clientHeight) {
    document.body.scrollTo({ top: targetY, behavior: 'smooth' })
  }
}

const scrollToCategory = (catId) => {
  isManualNav.value = true
  activeCategoryId.value = catId
  scrollActiveTabIntoView(catId)
  const el = document.getElementById(catId)
  if (el) {
    scrollToTargetElement(el, -112)
  }
  setTimeout(() => {
    isManualNav.value = false
  }, 900)
}

const scrollToComponent = (compId) => {
  if (!compId) return
  isManualNav.value = true
  const comp = allComponents.value.find(c => c.id === compId)
  if (comp) {
    activeCategoryId.value = comp.categoryId
    scrollActiveTabIntoView(comp.categoryId)
  }
  const el = document.getElementById(compId)
  if (el) {
    scrollToTargetElement(el, -115)
    el.classList.add('component-highlight-pulse')
    setTimeout(() => {
      el.classList.remove('component-highlight-pulse')
    }, 2000)
  }
  setTimeout(() => {
    isManualNav.value = false
  }, 900)
}

let observer = null

onMounted(() => {
  // IntersectionObserver to auto-update activeCategoryId when scrolling
  observer = new IntersectionObserver((entries) => {
    if (isManualNav.value) return
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const catId = entry.target.dataset.category || entry.target.id
        if (catId) {
          activeCategoryId.value = catId
          scrollActiveTabIntoView(catId)
        }
      }
    })
  }, {
    rootMargin: '-120px 0px -60% 0px'
  })

  categories.forEach(cat => {
    const catEl = document.getElementById(cat.id)
    if (catEl) observer.observe(catEl)

    cat.components.forEach(comp => {
      const compEl = document.getElementById(comp.id)
      if (compEl) {
        compEl.dataset.category = cat.id
        observer.observe(compEl)
      }
    })
  })
})

onUnmounted(() => {
  if (observer) observer.disconnect()
})
</script>

