<template>
  <div class="props-table-wrapper w-100">
    <table class="props-table">
      <thead>
        <tr>
          <th style="width: 26%; min-width: 160px;">Prop / Slot</th>
          <th style="width: 18%; min-width: 110px;">Tipe</th>
          <th style="width: 16%; min-width: 100px;">Default</th>
          <th style="min-width: 220px;">Deskripsi</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="item in tableItems" :key="item.name">
          <!-- Column 1: Prop / Slot Name & Badges -->
          <td class="align-top">
            <div class="d-flex align-items-center gap-1.5 flex-wrap">
              <code class="prop-name">{{ item.name }}</code>
              
              <!-- Slot Badge (Pastel Lime Green) -->
              <span
                v-if="isSlotItem(item)"
                class="badge-tag badge-tag-slot"
                title="Vue Template Slot"
              >
                slot
              </span>

              <!-- Event Badge (Pastel Sky Blue) -->
              <span
                v-else-if="isEventItem(item)"
                class="badge-tag badge-tag-event"
                title="Component Event Emit"
              >
                event
              </span>

              <!-- v-model Badge (Pastel Purple) -->
              <span
                v-else-if="isModelItem(item)"
                class="badge-tag badge-tag-model"
                title="Two-Way Data Binding (v-model)"
              >
                v-model
              </span>

              <!-- Method Badge (Pastel Amber) -->
              <span
                v-else-if="isMethodItem(item)"
                class="badge-tag badge-tag-method"
                title="Component Method"
              >
                method
              </span>

              <!-- Custom Badge Tag (fallback if provided directly) -->
              <span
                v-else-if="item.badge && item.badge !== 'required'"
                class="badge-tag"
                :class="getCustomBadgeClass(item.badge)"
              >
                {{ item.badge }}
              </span>

              <!-- Required Badge (Pastel Rose Red) - Can accompany v-model or regular prop -->
              <span
                v-if="isRequiredItem(item) && !isSlotItem(item) && !isEventItem(item)"
                class="badge-tag badge-tag-required"
                title="Wajib Diisi (Required Prop)"
              >
                required
              </span>
            </div>
          </td>

          <!-- Column 2: Tipe Data -->
          <td class="align-top">
            <span class="prop-type">{{ item.type }}</span>
          </td>

          <!-- Column 3: Nilai Default -->
          <td class="align-top">
            <span class="prop-default">
              {{ formatDefaultValue(item.default) }}
            </span>
          </td>

          <!-- Column 4: Deskripsi -->
          <td class="align-top">
            <span class="prop-desc">{{ item.description }}</span>
          </td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<script setup>
import { computed } from 'vue'

/**
 * @file PropsTable.vue
 * @description Enterprise-grade unified API reference table with plain minimal aesthetic
 * and semantic badges for slots, events, v-model, methods, and required props.
 */
const componentProps = defineProps({
  items: {
    type: Array,
    default: () => []
  },
  props: {
    type: Array,
    default: null
  },
  propsData: {
    type: Array,
    default: null
  }
})

const tableItems = computed(() => componentProps.propsData || componentProps.props || componentProps.items || [])

function isSlotItem(item) {
  return Boolean(
    item.isSlot ||
    item.badge === 'slot' ||
    item.name?.startsWith('#') ||
    item.type?.toLowerCase() === 'slot'
  )
}

function isEventItem(item) {
  return Boolean(
    item.isEvent ||
    item.badge === 'event' ||
    item.name?.startsWith('@') ||
    item.name?.startsWith('update:') ||
    item.type?.toLowerCase() === 'event'
  )
}

function isModelItem(item) {
  return Boolean(
    item.isModel ||
    item.badge === 'v-model' ||
    item.name === 'modelValue' ||
    item.name === 'value' ||
    item.name?.startsWith('v-model')
  )
}

function isMethodItem(item) {
  return Boolean(
    item.isMethod ||
    item.badge === 'method' ||
    item.type?.toLowerCase() === 'function' ||
    item.type?.toLowerCase() === 'method' ||
    item.name?.endsWith('()')
  )
}

function isRequiredItem(item) {
  return Boolean(
    item.required === true ||
    item.isRequired === true ||
    item.badge === 'required'
  )
}

function formatDefaultValue(val) {
  if (val === undefined || val === null || val === '') return '-'
  return String(val)
}
</script>

