// Sampel Dummy Image Base64 KTP
const sampleKtpSvg = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="300" height="190" viewBox="0 0 300 190"><rect width="300" height="190" fill="%23e8f5e9" rx="8"/><rect x="20" y="20" width="70" height="90" fill="%23a5d6a7" rx="4"/><rect x="105" y="25" width="160" height="12" fill="%232e7d32" rx="2"/><rect x="105" y="45" width="130" height="10" fill="%2381c784" rx="2"/><rect x="105" y="65" width="140" height="10" fill="%2381c784" rx="2"/><rect x="105" y="85" width="100" height="10" fill="%2381c784" rx="2"/><text x="150" y="160" font-family="sans-serif" font-size="12" fill="%231b5e20" text-anchor="middle" font-weight="bold">KTP ELEKTRONIK REKAMAN</text></svg>'

// State Varian (10 Varian Lengkap)
const v1PhotoKtp = ref('')
const v2PhotoGeneral = ref('')
const v4PhotoTimestamp = ref('')
const v5PhotoCompression = ref('')
const v6PhotoExisting = ref(sampleKtpSvg)
const v7PhotoBottomSheet = ref('')
const v8PhotoTitle = ref('')
const v9PhotoUserName = ref('')
const v10PhotoSlot = ref(sampleKtpSvg)

const resetV6Sample = () => {
  v6PhotoExisting.value = sampleKtpSvg
}

// State Real Case
const activePreset = ref('empty')
const rcKtpPhoto = ref('')
const rcDebiturData = reactive({
  nik: '',
  nama: '',
  ttl: ''
})

const applyPreset = (mode) => {
  activePreset.value = mode
  if (mode === 'ahmad') {
    rcKtpPhoto.value = sampleKtpSvg
    rcDebiturData.nik = '3273151908870002'
    rcDebiturData.nama = 'Ahmad Riyadi'
    rcDebiturData.ttl = 'Bandung, 19 Agustus 1987'
  } else if (mode === 'dewi') {
    rcKtpPhoto.value = sampleKtpSvg
    rcDebiturData.nik = '3171026504910005'
    rcDebiturData.nama = 'Hj. Dewi Lestari'
    rcDebiturData.ttl = 'Jakarta, 25 April 1991'
  } else {
    resetKtpRealCase()
  }
}

const loadSampleKtp = () => {
  applyPreset('ahmad')
}

const handleKtpDropped = () => {
  if (!rcDebiturData.nik) {
    rcDebiturData.nik = '3273151908870002'
    rcDebiturData.nama = 'Ahmad Riyadi'
    rcDebiturData.ttl = 'Bandung, 19 Agustus 1987'
    activePreset.value = 'ahmad'
  }
}

const resetKtpRealCase = () => {
  activePreset.value = 'empty'
  rcKtpPhoto.value = ''
  rcDebiturData.nik = ''
  rcDebiturData.nama = ''
  rcDebiturData.ttl = ''
}

const bukaTabunganEmas = () => {
  alert('e-KTP berhasil diverifikasi! Buku Rekening Tabungan Emas nasabah berhasil diterbitkan.')
}

// Props Matrix Documentation
const inputKtpProps = [
  {
    name: 'v-model',
    type: 'String (DataURL / URL)',
    default: 'undefined',
    description: 'Model data dua arah untuk berkas gambar KTP yang berhasil diambil atau diunggah.'
  },
  {
    name: 'title',
    type: 'String',
    default: "'Upload Foto KTP'",
    description: 'Judul modal dialog pemilihan sumber dan dialog kamera pengambilan KTP.'
  },
  {
    name: 'userName',
    type: 'String',
    default: "'unknown'",
    description: 'Nama petugas kasir/nasabah untuk dicantumkan pada stempel watermark foto.'
  },
  {
    name: 'timestamp',
    type: 'Boolean',
    default: 'false',
    description: 'Mengaktifkan stempel waktu perekaman foto otomatis.'
  },
  {
    name: 'takenPrefix',
    type: 'Boolean',
    default: 'false',
    description: 'Menambahkan awalan "Diambil Oleh: [userName]" pada stempel foto.'
  },
  {
    name: 'compressionMaxKb',
    type: 'Number',
    default: '1024',
    description: 'Batas ukuran berkas terkompresi dalam satuan Kilobyte (KB).'
  },
  {
    name: 'error',
    type: 'String | Boolean',
    default: 'undefined',
    description: 'Menampilkan status visual error border merah dan pesan peringatan di bawah input.'
  },
  {
    name: 'mode',
    type: "String ('ktp' | 'general')",
    default: "'ktp'",
    description: 'Mode framing kamera. Gunakan "ktp" untuk orientasi bingkai kartu identitas.'
  },
  {
    name: 'useBottomSheet',
    type: 'Boolean',
    default: 'false',
    description: 'Menampilkan dialog pemilihan sumber foto sebagai Bottom Sheet ramah mobile.'
  },
  {
    name: '#footer',
    type: 'Scoped Slot ({ close })',
    default: '-',
    description: 'Slot kustom tombol aksi (approval/tolak) di bagian bawah modal pratinjau.'
  }
]
