<script setup>
defineOptions({
  name: 'StepperSection'
})

import { ref, reactive } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Stepper from '@/components/Stepper/Stepper.vue'
import Button from '@/components/Button/Button.vue'
import Badge from '@/components/Badge/Badge.vue'
import Alert from '@/components/Alert/AlertVarian.vue'

// State Varian
const defaultSteps = [
  'Identitas Nasabah',
  'Taksiran Marhun',
  'Persetujuan SBG',
  'Pencairan Kas'
]

const custom5Steps = [
  'Pendaftaran Loket',
  'Taksiran Karatase',
  'Persetujuan Plafon',
  'Tanda Tangan Akad',
  'Pencairan Tunai'
]

const v1Step = ref(1)
const v2Step = ref(2)
const v4Step = ref(3)

// State Real Case
const kcaSteps = [
  'Data Nasabah',
  'Taksiran Agunan',
  'Kalkulasi Plafon',
  'Penerbitan SBG'
]

const rcActiveStep = ref(1)
const rcMaxCompletedStep = ref(1)
const lastRcStatus = ref('Sedang memverifikasi Identitas Nasabah di Loket 01')

const formData = reactive({
  nik: '3175082104880002',
  nama: 'Ir. Hendra Gunawan',
  telepon: '0812-9876-5432',
  jenisBarang: 'Kalung Emas Kuning 24K',
  karatase: '24 Karat (Kadar 99.9%)',
  berat: '15.00 gram',
  nilaiTaksiran: 'Rp 15.000.000'
})

const handleRcStepChange = (step) => {
  rcActiveStep.value = step
  lastRcStatus.value = `Berpindah ke langkah ${step}: ${kcaSteps[step - 1]}`
}

const prevRcStep = () => {
  if (rcActiveStep.value > 1) {
    rcActiveStep.value--
    lastRcStatus.value = `Kembali ke langkah ${rcActiveStep.value}: ${kcaSteps[rcActiveStep.value - 1]}`
  }
}

const nextRcStep = () => {
  if (rcActiveStep.value < 4) {
    rcActiveStep.value++
    if (rcActiveStep.value > rcMaxCompletedStep.value) {
      rcMaxCompletedStep.value = rcActiveStep.value
    }
    lastRcStatus.value = `Maju ke langkah ${rcActiveStep.value}: ${kcaSteps[rcActiveStep.value - 1]}`
  }
}

const completeRcTransaction = () => {
  alert('Surat Bukti Gadai (SBG) #10234-26-01-009941 berhasil diterbitkan dan dana Rp 12.000.000 telah dicairkan!')
}

function resetRcStep() {
  rcActiveStep.value = 1
  rcMaxCompletedStep.value = 1
  lastRcStatus.value = 'Alur pengajuan direset kembali ke Langkah 1 (Identitas Nasabah)'
}

function loadRcStep() {
  rcActiveStep.value = 4
  rcMaxCompletedStep.value = 4
  lastRcStatus.value = 'Simulasi alur lengkap selesai tervalidasi hingga Langkah 4 (Penerbitan SBG)'
}

const stepperProps = [
  {
    name: 'label',
    type: 'String',
    default: "'Langkah'",
    description: 'Teks label judul tahapan di bagian atas kartu stepper.'
  },
  {
    name: 'items',
    type: 'Array<String>',
    default: "['MENU 1', 'MENU 2', ...]",
    description: 'Kumpulan nama tahapan proses yang akan ditampilkan berurutan dari atas ke bawah.'
  },
  {
    name: 'activeStep',
    type: 'Number',
    default: '0',
    description: 'Nomor indeks langkah yang sedang aktif (dimulai dari indeks 1).'
  },
  {
    name: 'enableStepUntill',
    type: 'Number',
    default: '0',
    description: 'Membatasi interaksi klik: hanya langkah bernomor <= enableStepUntill yang dapat diklik oleh pengguna.'
  },
  {
    name: '@update:activeStep',
    type: 'Event (Number)',
    default: '-',
    description: 'Dipancarkan saat pengguna mengklik butir langkah yang diizinkan untuk mengubah status langkah aktif (mendukung v-model:activeStep).'
  }
]
</script>

