<script setup>
import { ref, reactive } from 'vue'
import InputCamera from '@/components/Input/InputCamera.vue'
import Button from '@/components/Button/Button.vue'
import Badge from '@/components/Badge/Badge.vue'
import DocCard from '../components/DocCard.vue'
import PropsTable from '../components/PropsTable.vue'
import PlaygroundAlert from '../components/PlaygroundAlert.vue'

// Sampel Dummy Image Base64 (SVG Placeholder rasio 16:10 standar KTP)
const sampleKtpSvg = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="300" height="190" viewBox="0 0 300 190"><rect width="300" height="190" fill="%23e8f5e9" rx="8"/><rect x="20" y="20" width="70" height="90" fill="%23a5d6a7" rx="4"/><rect x="105" y="25" width="160" height="12" fill="%232e7d32" rx="2"/><rect x="105" y="45" width="130" height="10" fill="%2381c784" rx="2"/><rect x="105" y="65" width="140" height="10" fill="%2381c784" rx="2"/><rect x="105" y="85" width="100" height="10" fill="%2381c784" rx="2"/><text x="150" y="160" font-family="sans-serif" font-size="12" fill="%231b5e20" text-anchor="middle" font-weight="bold">KTP ELEKTRONIK REKAMAN</text></svg>'

// State Varian (6 Varian Lengkap)
const v1PhotoKtp = ref('')
const v2PhotoBarang = ref('')
const v3CardGeneral = ref('')
const v4BottomSheet = ref('')
const v5Compression = ref('')
const v6PhotoExisting = ref(sampleKtpSvg)

const resetV6Sample = () => {
  v6PhotoExisting.value = sampleKtpSvg
}

// State Real Case
const activePreset = ref('empty')
const rcKtpPhoto = ref('')
const rcKtpData = reactive({
  nik: '',
  nama: '',
  plafond: '-'
})

const applyPreset = (mode) => {
  activePreset.value = mode
  if (mode === 'budi') {
    rcKtpPhoto.value = sampleKtpSvg
    rcKtpData.nik = '3174051208850003'
    rcKtpData.nama = 'Budi Darmawan'
    rcKtpData.plafond = 'Rp 50.000.000 (Reguler UPK)'
  } else if (mode === 'siti') {
    rcKtpPhoto.value = sampleKtpSvg
    rcKtpData.nik = '3174095403880007'
    rcKtpData.nama = 'Hj. Siti Rahmawati'
    rcKtpData.plafond = 'Rp 150.000.000 (Nasabah Prioritas)'
  } else {
    resetKtpRealCase()
  }
}

const loadSampleDebitur = () => {
  applyPreset('budi')
}

const handleKtpDropped = () => {
  if (!rcKtpData.nik) {
    rcKtpData.nik = '3174051208850003'
    rcKtpData.nama = 'Budi Darmawan'
    rcKtpData.plafond = 'Rp 50.000.000 (Reguler UPK)'
    activePreset.value = 'budi'
  }
}

const handleKtpRemoved = () => {
  resetKtpRealCase()
}

const resetKtpRealCase = () => {
  activePreset.value = 'empty'
  rcKtpPhoto.value = ''
  rcKtpData.nik = ''
  rcKtpData.nama = ''
  rcKtpData.plafond = '-'
}

const lanjutTaksiran = () => {
  alert('Foto KTP nasabah berhasil diverifikasi. Lanjut ke proses penaksiran karatase emas!')
}

// Props Matrix Documentation
const inputCameraProps = [
  {
    name: 'v-model',
    type: 'String (DataURL / URL)',
    default: 'undefined',
    description: 'Binding data dua arah untuk berkas gambar yang telah diambil dari kamera atau diunggah.'
  },
  {
    name: 'title',
    type: 'String',
    default: "'Upload Foto'",
    description: 'Judul modal dialog pemilihan sumber foto (Galeri / Kamera) dan header modal pengambilan gambar.'
  },
  {
    name: 'imagePlaceholder',
    type: "String ('idcard' | 'card-general')",
    default: 'undefined',
    description: "Mode placeholder visual & panduan framing. Isi dengan 'idcard' untuk bingkai kartu identitas KTP."
  },
  {
    name: 'compressionMaxKb',
    type: 'Number',
    default: '1024',
    description: 'Batas kapasitas berkas maksimum terkompresi otomatis dalam satuan Kilobyte (KB).'
  },
  {
    name: 'useBottomSheet',
    type: 'Boolean',
    default: 'false',
    description: 'Menentukan apakah dialog pemilihan sumber foto ditampilkan sebagai Bottom Sheet pada mode mobile.'
  },
  {
    name: 'userName',
    type: 'String',
    default: "'unknown'",
    description: 'Nama identitas petugas kasir/nasabah untuk pencatatan stempel audit metadata foto.'
  },
  {
    name: 'general',
    type: 'Boolean',
    default: 'false',
    description: 'Mode rasio aspek umum (1:1) tanpa overlay framing kartu identitas.'
  },
  {
    name: '@fileDropped',
    type: 'Event (File, uniqueKey)',
    default: '-',
    description: 'Dipancarkan ketika berkas foto berhasil diambil atau dipilih dan selesai dikompresi.'
  },
  {
    name: '@fileRemoved',
    type: 'Event',
    default: '-',
    description: 'Dipancarkan ketika tombol hapus pada pratinjau thumbnail diklik oleh pengguna.'
  }
]
</script>

