<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import TimePickerResponsive from '@/components/Input/TimePickerResponsive.vue'

// Real-world scenario state
const rcWaktuKonsultasi = ref('11:00')

function resetScenarioData() {
  rcWaktuKonsultasi.value = ''
}

function loadScenarioData() {
  rcWaktuKonsultasi.value = '14:00'
}

const assignedAppraiser = computed(() => {
  if (!rcWaktuKonsultasi.value) return 'Belum dialokasikan'
  const hour = parseInt(rcWaktuKonsultasi.value.split(':')[0], 10)
  if (hour < 12) return 'Bpk. H. Rendra Wijaya, S.E. (Penaksir Emas Mulia)'
  if (hour < 15) return 'Ibu Dian Pitaloka, S.T. (Penaksir Berlian & Permata)'
  return 'Bpk. Arif Wicaksono (Penaksir Jam Tangan Mewah)'
})

const reservationToken = computed(() => {
  if (!rcWaktuKonsultasi.value) return 'QR-NONE'
  const clean = rcWaktuKonsultasi.value.replace(':', '')
  return `QR-VIP-20260902-${clean}`
})

// Lifecycle states
const stateDefault = ref('08:00')
const statePreselected = ref('10:30')
const stateDisabled = ref('09:00')

const selectedTimesGlobal = ref('10:24')
const lastEmittedTime = ref('')
const handleSelectedTime = (time) => {
  lastEmittedTime.value = time
}

// Props Matrix Documentation
const timePickerResponsiveProps = [
  {
    name: 'modelValue',
    type: 'String (HH:mm)',
    default: "''",
    description: 'Nilai waktu yang terpilih (two-way binding via v-model) dalam format 24 jam.'
  },
  {
    name: 'title',
    type: 'String',
    default: "''",
    description: 'Label teks judul yang ditampilkan di atas kolom input waktu.'
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "''",
    description: 'Teks instruksi placeholder sebelum pengguna menentukan jam kedatangan.'
  },
  {
    name: 'error',
    type: 'String',
    default: "''",
    description: 'Pesan kesalahan validasi di bawah input yang menambahkan indikator border merah is-invalid.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi pada timepicker dan meredam visual komponen.'
  },
  {
    name: 'required',
    type: 'Boolean',
    default: 'false',
    description: 'Menandai kolom isian waktu wajib dilengkapi pada formulir.'
  },
  {
    name: '@selectedTimeUpdated',
    type: 'Event Payload (String)',
    default: '-',
    description: "Dipancarkan saat pengguna mengonfirmasi waktu baru dengan payload format 'HH:mm'."
  }
]
</script>
