import { createRouter, createWebHistory, createWebHashHistory } from "vue-router";
import App from "../components/GlobalComponent.vue";
import Camera from "../components/Input/InputCamera.vue";
import PlaygroundPage from "../playground/PlaygroundPage.vue";

const routes = [
  {
    path: "/",
    name: "Home",
    component: PlaygroundPage,
  },
  {
    path: "/playground",
    name: "Playground",
    component: PlaygroundPage,
  },
  {
    path: "/global",
    name: "GlobalComponent",
    component: App,
  },
  {
    path: "/camera",
    name: "camera",
    component: Camera,
  },
  {
    path: "/dashboard-360",
    name: "Dashboard360NasabahPrioritas",
    component: () => import("../views/Dashboard360NasabahPrioritas.vue"),
  },
];

const router = createRouter({
  history: process.env.NODE_ENV === "production" ? createWebHashHistory() : createWebHistory(process.env.BASE_URL),
  routes,
});

export default router;