<script setup>
defineOptions({
  name: 'TestCalendarSection'
})
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import testCalendar from '@/components/Input/testCalendar.vue'

// Real-world scenario state
const rcTanggalSimulasi = ref('2026-09-15')

function resetScenarioData() {
  rcTanggalSimulasi.value = ''
}

function loadScenarioData() {
  rcTanggalSimulasi.value = '2026-09-25'
}

function formatIndoMonth(d) {
  return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'long', year: 'numeric' }).format(d)
}

const installmentDates = computed(() => {
  if (!rcTanggalSimulasi.value) return ['-', '-', '-']
  const base = new Date(rcTanggalSimulasi.value)
  if (isNaN(base.getTime())) return ['-', '-', '-']
  
  const dates = []
  for (let i = 1; i <= 3; i++) {
    const nextMonth = new Date(base)
    nextMonth.setMonth(base.getMonth() + i)
    dates.push(formatIndoMonth(nextMonth))
  }
  return dates
})

// Lifecycle states
const stateDefault = ref('')
const statePreselected = ref('2026-09-10')
const stateDisabled = ref('2026-08-01')

// Props Matrix Documentation
const testCalendarProps = [
  {
    name: 'modelValue',
    type: 'String',
    default: "''",
    description: 'Nilai tanggal yang terpilih (two-way binding via v-model).'
  },
  {
    name: 'title',
    type: 'String',
    default: "'Tanggal Lahir'",
    description: 'Label judul yang ditampilkan di atas kolom input kalender.'
  },
  {
    name: 'placeholder',
    type: 'String',
    default: "''",
    description: 'Teks instruksi placeholder sebelum tanggal ditentukan.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi kalender dan menerapkan visual teredam.'
  },
  {
    name: 'required',
    type: 'Boolean',
    default: 'false',
    description: 'Menandai kolom isian wajib diisi pada formulir.'
  }
]
