<script setup>
import { computed } from 'vue'
import InputText from './InputText.vue'

defineOptions({
  name: 'InputNominalStart'
})

const props = defineProps({
  modelValue: {},
  placeholder: {},
  unit: {},
  label: {
    type: String,
    default: ''
  },
  error: {
    type: [String, Boolean],
    default: ''
  },
  helperText: {
    type: String,
    default: ''
  },
  disabled: {
    type: Boolean,
    default: false
  }
})
const emit = defineEmits(['update:modelValue'])

const rupiahValue = computed({
  get() {
    return formatDecimal(props.modelValue)
  },
  set(newValue) {
    emit('update:modelValue', unformatDecimal(newValue))
  }
})

const formatDecimal = (value) => {
  if (value === null || value === undefined || value === '') return ''
  const numericValue = value.toString().replace(/\D/g, '')
  return numericValue.replace(/\B(?=(\d{3})+(?!\d))/g, '.')
}

const unformatDecimal = (value) => {
  if (!value) return ''
  return value.replace(/\./g, '')
}

const onlyNumber = (event) => {
  // Izinkan shortcut keyboard (Ctrl/Cmd + A, C, V, X)
  if (event.ctrlKey || event.metaKey) {
    return
  }

  // Izinkan tombol navigasi dan kontrol standar
  const allowedKeys = [
    'Backspace',
    'Delete',
    'Tab',
    'Escape',
    'Enter',
    'ArrowLeft',
    'ArrowRight',
    'ArrowUp',
    'ArrowDown',
    'Home',
    'End',
  ]
  if (allowedKeys.includes(event.key)) {
    return
  }

  // Izinkan angka 0-9
  if (/^[0-9]$/.test(event.key)) {
    return
  }

  // Fallback untuk keyCode legacy
  const keyCode = event.keyCode ? event.keyCode : event.which
  if (
    (keyCode >= 48 && keyCode <= 57) || // Numbers
    (keyCode >= 96 && keyCode <= 105) || // Numpad
    keyCode === 46 || // Delete
    keyCode === 8 || // Backspace
    keyCode === 9 || // Tab
    keyCode === 37 || // ArrowLeft
    keyCode === 39 || // ArrowRight
    keyCode === 35 || // End
    keyCode === 36 || // Home
    keyCode === 190 || // Period
    keyCode === 110 || // Numpad Period
    keyCode === 189 || // Dash/Minus
    keyCode === 109 // Numpad Dash/Minus
  ) {
    return
  }

  event.preventDefault()
}
</script>

<template>
  <div class="input-nominal-start-wrapper">
    <slot name="label" />
    <InputText
      rupiah="rupiah"
      v-model="rupiahValue"
      @keydown="onlyNumber"
      :placeholder="props.placeholder || 'Masukkan rupiah'"
      type="text"
      :use-delimiter="false"
      :label="props.label"
      :error="props.error"
      :helper-text="props.helperText"
      :disabled="props.disabled"
      v-bind="$attrs"
    >
      <template #prefix>
        <span class="input-group-text border-0">{{ props.unit || "Rupiah" }}</span>
      </template>
      <template #suffix>
        <slot name="suffix" />
      </template>
      <template #label-icon>
        <slot name="label-icon" />
      </template>
    </InputText>
  </div>
</template>

