<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import InputNominalEnd from '@/components/Input/InputNominalEnd.vue'

// Real-world scenario state
const rcPersen = ref('1.15')
const rcBerat = ref('14.75')

function resetScenarioData() {
  rcPersen.value = ''
  rcBerat.value = ''
}

function loadScenarioData() {
  rcPersen.value = '1.20'
  rcBerat.value = '25.50'
}

function setPreset(berat, persen) {
  rcBerat.value = berat
  rcPersen.value = persen
}

function formatRupiah(val) {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency',
    currency: 'IDR',
    maximumFractionDigits: 0
  }).format(val || 0)
}

// Appraisal & Ujrah Calculation Engine
const appraisalCalculation = computed(() => {
  const berat = parseFloat(String(rcBerat.value || '').replace(',', '.')) || 0
  const persen = parseFloat(String(rcPersen.value || '').replace(',', '.')) || 0
  const hpsPerGram = 1350000 // Standar HPS Emas Pegadaian

  if (berat === 0) {
    return {
      hpsPerGram,
      taksiranPasar: 0,
      plafonMaksimal: 0,
      ujrah15Hari: 0,
      totalUjrah120Hari: 0,
      message: 'Masukkan berat bersih timbangan untuk menghitung nilai taksir'
    }
  }

  const taksiranPasar = Math.round(berat * hpsPerGram)
  const plafonMaksimal = Math.round(taksiranPasar * 0.85) // LTV 85%
  const ujrah15Hari = Math.round(plafonMaksimal * (persen / 100))
  const totalUjrah120Hari = Math.round(ujrah15Hari * 8) // 120 hari = 8 siklus 15 hari

  return {
    hpsPerGram,
    taksiranPasar,
    plafonMaksimal,
    ujrah15Hari,
    totalUjrah120Hari,
    message: `Taksiran Emas Sah: Plafon Maksimal ${formatRupiah(plafonMaksimal)}`
  }
})

// Lifecycle states
const statePersen = ref('0.75')
const stateGram = ref('10.50')
const stateTenor = ref('120')

// Props Matrix Documentation
const nominalEndProps = [
  {
    name: 'modelValue',
    type: 'String | Number',
    default: "''",
    description: 'Nilai angka mentah yang terikat via two-way binding v-model.'
  },
  {
    name: 'title',
    type: 'String',
    default: "'Title'",
    description: 'Teks label judul di atas kolom input numerik.'
  },
  {
    name: 'unit',
    type: 'String',
    default: "'%'",
    description: "Teks penanda satuan di sisi kanan input (misal: '%', 'Gram', 'Hari', 'Bulan')."
  },
  {
    name: 'delimeter',
    type: "'comma' | 'dot' | 'none'",
    default: "'comma'",
    description: 'Format pemisah ribuan atau desimal yang diterapkan pada saat pengetikan.'
  },
  {
    name: 'required',
    type: 'Boolean',
    default: 'false',
    description: 'Menandai kolom wajib diisi pada validasi formulir.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi pada kolom input.'
  },
  {
    name: 'error',
    type: 'Boolean',
    default: 'false',
    description: 'Status kesalahan validasi yang mengaktifkan styling border error.'
  },
  {
    name: 'errorMessage',
    type: 'String',
    default: "''",
    description: 'Pesan kustom yang ditampilkan saat terjadi kesalahan validasi.'
  },
  {
    name: 'id',
    type: 'String',
    default: "'addon'",
    description: 'Identifier unik elemen untuk binding label aksesibilitas.'
  },
  {
    name: '@update:modelValue',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat nilai nominal desimal/angka berubah (sinkronisasi v-model).'
  }
]
</script>
