<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import { BFormCheckbox } from 'bootstrap-vue-next'

// Real-world scenario state
const agreeAkad = ref(true)
const agreePDP = ref(true)
const agreePromo = ref(false)
const activePreset = ref('mandatory')

const mandatoryConsentCount = computed(() => {
  let count = 0
  if (agreeAkad.value) count++
  if (agreePDP.value) count++
  return count
})

const mandatoryConsentPercentage = computed(() => {
  return Math.round((mandatoryConsentCount.value / 2) * 100)
})

const isLegallyCompliant = computed(() => agreeAkad.value && agreePDP.value)

const digitalHash = computed(() => {
  if (!isLegallyCompliant.value) {
    return 'DOKUMEN_BELUM_DITANDATANGANI_LEGAL'
  }
  const promoFlag = agreePromo.value ? '1' : '0'
  return `SHA256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855#P${promoFlag}`
})

function applyPreset(preset) {
  activePreset.value = preset
  if (preset === 'full') {
    agreeAkad.value = true
    agreePDP.value = true
    agreePromo.value = true
  } else if (preset === 'mandatory') {
    agreeAkad.value = true
    agreePDP.value = true
    agreePromo.value = false
  } else if (preset === 'rejected') {
    agreeAkad.value = false
    agreePDP.value = false
    agreePromo.value = false
  }
}

function checkCustomPreset() {
  if (agreeAkad.value && agreePDP.value && agreePromo.value) {
    activePreset.value = 'full'
  } else if (agreeAkad.value && agreePDP.value && !agreePromo.value) {
    activePreset.value = 'mandatory'
  } else if (!agreeAkad.value && !agreePDP.value && !agreePromo.value) {
    activePreset.value = 'rejected'
  } else {
    activePreset.value = 'custom'
  }
}

function handleCardClick(field, event) {
  // If user clicked directly on the input or its label, let native input handle it
  if (event && (event.target.closest('.form-check-input') || event.target.closest('.form-check-label'))) {
    return
  }
  if (field === 'akad') agreeAkad.value = !agreeAkad.value
  if (field === 'pdp') agreePDP.value = !agreePDP.value
  if (field === 'promo') agreePromo.value = !agreePromo.value
  checkCustomPreset()
}

function resetScenarioData() {
  applyPreset('rejected')
}

function loadScenarioData() {
  applyPreset('full')
}

// Lifecycle states
const stateBoolean = ref(true)
const stateCustomValue = ref('DISETUJUI_KASIR')
const stateInline1 = ref(true)
const stateInline2 = ref(false)
const stateInline3 = ref(true)

// Props Matrix Documentation
const bCheckboxProps = [
  {
    name: 'modelValue',
    type: 'Boolean | Array | Any',
    default: 'false',
    isModel: true,
    description: 'Nilai data aktif yang terikat secara two-way binding via v-model.'
  },
  {
    name: 'value',
    type: 'Any',
    default: 'true',
    description: 'Nilai kustom yang dipancarkan saat checkbox dalam kondisi tercentang.'
  },
  {
    name: 'uncheckedValue',
    type: 'Any',
    default: 'false',
    description: 'Nilai kustom yang dipancarkan saat checkbox dalam kondisi tidak tercentang.'
  },
  {
    name: 'disabled',
    type: 'Boolean',
    default: 'false',
    description: 'Menonaktifkan interaksi klik dan menerapkan visual muted pada kontrol.'
  },
  {
    name: 'inline',
    type: 'Boolean',
    default: 'false',
    description: 'Menata letak beberapa checkbox secara mendatar dalam satu baris.'
  },
  {
    name: 'name',
    type: 'String',
    default: "''",
    description: 'Nama atribut kelompok HTML form input.'
  },
  {
    name: 'id',
    type: 'String',
    default: "''",
    description: 'Identifier unik elemen untuk relasi semantik aksesibilitas label.'
  },
  {
    name: '@update:modelValue',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat status centang mengalami perubahan nilai.'
  },
  {
    name: '@change',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Event native change saat nilai kontrol formulir diperbarui.'
  }
]
</script>

