// Real-world scenario state
const realCaseNama = ref('AHMAD ZULKARNAIN')
const realCaseIbu = ref('SITI MARYAM')

function resetScenarioData() {
  realCaseNama.value = ''
  realCaseIbu.value = ''
}

function loadScenarioData() {
  realCaseNama.value = 'BUDI SANTOSO'
  realCaseIbu.value = 'SRI WAHYUNI'
}

function setPreset(nama, ibu) {
  realCaseNama.value = nama
  realCaseIbu.value = ibu
}

// AML/CFT & Biometric Screening Engine
const amlScreening = computed(() => {
  const nama = String(realCaseNama.value || '').trim()
  const ibu = String(realCaseIbu.value || '').trim()

  if (!nama || !ibu) {
    return {
      isApproved: false,
      badgeText: 'Menunggu Kelengkapan Data',
      matchScore: 'Menunggu Input',
      authorizationText: 'Belum Dapat Diterbitkan',
      message: 'Lengkapi nama pemohon dan nama ibu kandung untuk verifikasi'
    }
  }

  return {
    isApproved: true,
    badgeText: 'Lolos Verifikasi KYC',
    matchScore: '99.4% Terverifikasi Dukcapil',
    authorizationText: 'Otorisasi SBG Diberikan',
    message: 'Data nasabah terverifikasi valid dan bersih dari daftar sanksi terorisme'
  }
})

// Lifecycle states
const stateDefault = ref('')
const stateAutoCaps = ref('PGD-CAB-SALEMBA')
const stateDisabled = ref('CIF-9920148291')
const stateError = ref('budi.santoso@')

