    default: 'false',
    description: 'Menonaktifkan interaksi pada input dan memberi gaya visual muted.'
  },
  {
    name: 'required',
    type: 'Boolean',
    default: 'false',
    description: 'Menandai input wajib diisi dan menampilkan peringatan otomatis jika kosong.'
  },
  {
