    default: "''",
    description: 'Pesan kesalahan validasi di bawah input yang memicu garis batas merah.'
  },
  {
    name: 'helperText',
    type: 'String',
    default: "''",
    description: 'Teks panduan atau petunjuk tambahan yang ditampilkan di bawah input.'
  },
  {
    name: 'suffixIcon',
    type: 'String',
    default: "''",
    description: 'Path atau URL gambar/icon dekoratif di sisi kanan dalam input.'
  },
  {
    name: 'variant',
    type: 'String',
    default: "'default'",
    description: 'Varian tata letak visual komponen input.'
  },
  {
