  },
  {
    name: '#suffix',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot ornamen kustom di sisi kanan input setelah icon bawaan.'
  },
  {
    name: '@update:modelValue',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Event reaktif yang dipancarkan saat nilai masukan berubah (sinkronisasi v-model).'
  },
