              <div class="d-flex align-items-center justify-content-between">
                <span class="variant-state-name">Pre-selected Value</span>
                <span class="variant-prop-badge">v-model="2026-08-17"</span>
              </div>
              <p class="variant-note">Data tanggal yang telah terisi dan terformat rapi.</p>
            </div>
          </div>
        </div>

        <!-- State 3: Error Validation State -->
        <div class="col-12 col-md-4">
          <div class="playground-tile">
            <div>
              <InputDatePicker
                v-model="stateError"
                label="Tanggal Kadaluarsa Dokumen Legalitas"
                error="Tanggal dokumen tidak boleh lebih lampau dari hari ini"
              />
            </div>
            <div class="playground-tile-meta">
