<script setup>
import { ref, computed } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import Button from '@/components/Button/Button.vue'
import InputDatePicker from '@/components/Input/InputDatePicker.vue'

// Real-world scenario state
const rcTanggalLahir = ref('1995-05-12')

function resetScenarioData() {
  rcTanggalLahir.value = ''
}

function loadScenarioData() {
  rcTanggalLahir.value = '1998-11-20'
}

const calculatedAge = computed(() => {
  if (!rcTanggalLahir.value) return null
  const birth = new Date(rcTanggalLahir.value)
  if (isNaN(birth.getTime())) return null
  const now = new Date('2026-09-13')
  let age = now.getFullYear() - birth.getFullYear()
  const m = now.getMonth() - birth.getMonth()
  if (m < 0 || (m === 0 && now.getDate() < birth.getDate())) {
    age--
  }
  return age
})

const isAdult = computed(() => {
  return calculatedAge.value !== null && calculatedAge.value >= 17
})

const formattedBirthDate = computed(() => {
  if (!rcTanggalLahir.value) return 'Belum dipilih'
  const d = new Date(rcTanggalLahir.value)
  if (isNaN(d.getTime())) return '-'
  return new Intl.DateTimeFormat('id-ID', {
    day: 'numeric',
    month: 'long',
    year: 'numeric'
  }).format(d)
})

const eligibilityBadgeClass = computed(() => {
  if (calculatedAge.value === null) return 'bg-secondary-subtle text-secondary'
  if (calculatedAge.value < 17) return 'bg-danger-subtle text-danger border-danger-subtle'
  if (calculatedAge.value >= 65) return 'bg-warning-subtle text-dark border-warning-subtle'
  return 'bg-success-subtle text-success border-success-subtle'
})

const eligibilityBadgeText = computed(() => {
  if (calculatedAge.value === null) return 'Menunggu Pilihan Tanggal'
  if (calculatedAge.value < 17) return 'Di Bawah Umur (< 17 Thn)'
  if (calculatedAge.value >= 65) return 'Kategori Lansia (65+ Thn)'
  return 'Cakap Hukum OJK (17-64 Thn)'
})

const generationLabel = computed(() => {
  if (!rcTanggalLahir.value) return '-'
  const year = parseInt(rcTanggalLahir.value.substring(0, 4), 10)
  if (year >= 1997 && year <= 2012) return 'Generasi Z'
  if (year >= 1981 && year <= 1996) return 'Generasi Milenial (Gen Y)'
  if (year >= 1965 && year <= 1980) return 'Generasi X'
  if (year < 1965) return 'Baby Boomer'
  return 'Generasi Alpha'
})

const generatedCIF = computed(() => {
  if (!rcTanggalLahir.value) return 'CIF-XXXXXXXX-0000'
  const clean = rcTanggalLahir.value.replace(/-/g, '')
  return `CIF-${clean}-8829`
})

const kualifikasiStatusText = computed(() => {
  if (calculatedAge.value === null) return 'Silakan Tentukan Tanggal Lahir Nasabah'
  if (calculatedAge.value < 17) return 'Ditolak Otomatis: Belum Memenuhi Syarat Minimal 17 Tahun'
  if (calculatedAge.value >= 65) return 'Lolos Bersyarat: Disarankan Surat Pendampingan Ahli Waris'
  return 'Disetujui: Memenuhi Persyaratan Legal Akad Kredit Gadai'
})

// Lifecycle states
const stateDefault = ref('')
const statePreselected = ref('2026-08-17')
const stateError = ref('2024-01-01')

// Props Matrix Documentation
const inputDatePickerProps = [
  {
    name: 'modelValue',
    type: 'String (YYYY-MM-DD)',
    default: 'null',
    description: 'Nilai data tanggal dalam format standar ISO (YYYY-MM-DD), terikat two-way data binding via v-model.'
  },
  {
    name: 'label',
    type: 'String',
    default: "''",
    description: 'Label teks deskriptif yang diletakkan tepat di atas kolom isian tanggal.'
  },
  {
    name: 'error',
    type: 'String',
    default: "''",
    description: 'Pesan kesalahan validasi formulir yang otomatis memicu styling status is-invalid.'
  },
  {
    name: 'class',
    type: 'String',
    default: "''",
    description: 'Kelas CSS kustom untuk memperluas styling visual komponen.'
  }
]
</script>
