<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import DocCard from '@/playground/components/DocCard.vue'
import PropsTable from '@/playground/components/PropsTable.vue'
import AlertVarian from '@/components/Alert/AlertVarian.vue'
import Button from '@/components/Button/Button.vue'

// Real-world scenario state
const activePreset = ref('success')
const operatorLog = ref('Menunggu interaksi kasir pada banner...')

const alertPresets = {
  success: {
    color: 'green',
    variant: 'aksen',
    hideAction: false,
    label: 'Transaksi #SBG-2026-0819 berhasil diautentikasi oleh Penaksir Madya.'
  },
  warning: {
    color: 'yellow',
    variant: 'warning',
    hideAction: true,
    label: 'Plafon kas tunai cabang tersisa 12% dari batas aman harian Bank Indonesia.'
  },
  danger: {
    color: 'red',
    variant: 'danger',
    hideAction: true,
    label: 'Agunan perhiasan ditolak: Kadar karatase terdeteksi di bawah 16 karat (tidak memenuhi SOP).'
  },
  info: {
    color: 'light-blue',
    variant: 'aksen',
    hideAction: false,
    label: 'Layanan taksir online emas batangan beroperasi mulai pukul 08.00 s.d. 15.00 WIB.'
  }
}

const currentAlert = computed(() => alertPresets[activePreset.value] || alertPresets.success)

function applyPreset(preset) {
  activePreset.value = preset
  operatorLog.value = `Sinyal notifikasi ${preset.toUpperCase()} dimuat pada bilah pemantauan kasir.`
}

function handleActionLog(actionText) {
  operatorLog.value = `Tombol '${actionText}' berhasil ditekan pada banner.`
}

function resetScenarioData() {
  applyPreset('info')
}

function loadScenarioData() {
  applyPreset('success')
}

// Lifecycle State 11 Timer
const showAlertDismissible = ref(true)
const countdownSec = ref(10)
let timer = null

onMounted(() => {
  timer = setInterval(() => {
    if (countdownSec.value > 1) {
      countdownSec.value--
    } else {
      showAlertDismissible.value = false
    }
  }, 1000)
})

onUnmounted(() => {
  if (timer) clearInterval(timer)
})

function resetDismissible() {
  countdownSec.value = 10
  showAlertDismissible.value = true
}

function handleActionClick() {
  operatorLog.value = 'Rincian tarif sewa modal dibuka oleh pengguna.'
}

// Props Matrix Documentation
const alertProps = [
  {
    name: 'label',
    type: 'String',
    default: "''",
    description: 'Pesan teks utama yang disampaikan di dalam banner notifikasi.'
  },
  {
    name: 'color',
    type: "'green' | 'light-blue' | 'yellow' | 'red' | 'link'",
    default: "'-'",
    description: 'Skema warna resmi Pegadaian atau tipe link untuk tautan teks transparan.'
  },
  {
    name: 'variant',
    type: "'success' | 'info' | 'warning' | 'danger' | 'aksen'",
    default: "'-'",
    description: 'Penetap visual: kelas solid Bootstrap pekat atau aksen untuk latar pastel lembut ber-watermark grafis.'
  },
  {
    name: 'hideAction',
    type: 'Boolean',
    default: 'true',
    description: 'Menyembunyikan slot aksi di sisi kanan banner secara default bila disetel true.'
  },
  {
    name: '#action',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Slot kustom untuk menyematkan tombol interaktif di kolom kanan banner.'
  }
]
</script>
