import DropdownItem from '@/components/Dropdown/DropdownItem.vue'
import Badge from '@/components/Badge/Badge.vue'
import Button from '@/components/Button/Button.vue'
import DocCard from '../components/DocCard.vue'
import PropsTable from '../components/PropsTable.vue'

// Card 1: Scenario Data
const scenarioDecisionCode = ref('')
const scenarioDecisionText = ref('')

const setScenarioDecision = (code, text) => {
  scenarioDecisionCode.value = code
  scenarioDecisionText.value = text
}

const scenarioDecisionKey = computed(() => {
  if (scenarioDecisionCode.value === 'SETUJUI') return 'DISETUJUI'
  if (scenarioDecisionCode.value === 'UJI_ULANG') return 'PERLU_UJI'
  if (scenarioDecisionCode.value === 'TOLAK') return 'DITOLAK'
  return 'MENUNGGU'
})

const scenarioBadgeClass = computed(() => {
  if (scenarioDecisionCode.value === 'SETUJUI') return 'bg-success-subtle text-success border-success-subtle'
  if (scenarioDecisionCode.value === 'UJI_ULANG') return 'bg-warning-subtle text-warning border-warning-subtle'
  if (scenarioDecisionCode.value === 'TOLAK') return 'bg-danger-subtle text-danger border-danger-subtle'
  return 'bg-secondary-subtle text-secondary border-secondary-subtle'
})

const nextActionText = computed(() => {
  if (scenarioDecisionCode.value === 'SETUJUI') return 'Kirim ke Kasir & Cetak SBG'
  if (scenarioDecisionCode.value === 'UJI_ULANG') return 'Kembalikan ke Meja Uji Asam'
  if (scenarioDecisionCode.value === 'TOLAK') return 'Buat Berita Acara Penolakan'
  return 'Menunggu Tindakan Pimpinan'
})

const scenarioStatusClass = computed(() => {
  if (scenarioDecisionCode.value === 'SETUJUI') return 'text-success'
  if (scenarioDecisionCode.value === 'UJI_ULANG') return 'text-warning'
  if (scenarioDecisionCode.value === 'TOLAK') return 'text-danger'
  return 'text-secondary'
})

function resetScenarioData() {
  scenarioDecisionCode.value = ''
  scenarioDecisionText.value = ''
}

function loadScenarioData() {
  scenarioDecisionCode.value = 'SETUJUI'
  scenarioDecisionText.value = 'Otorisasi Disetujui: Siap Pencairan Kas'
}

// Card 2: Lifecycle States
const tileClick = ref('')

// Card 3: Props Matrix Documentation
const dropdownItemProps = [
  {
    name: '#default',
    type: 'Slot',
    isSlot: true,
    default: '-',
    description: 'Konten teks label, ikon tambahan, atau komponen Badge status di dalam tombol baris menu.'
  },
  {
    name: '@click',
    type: 'Event',
    isEvent: true,
    default: '-',
    description: 'Dipancarkan saat pengguna mengklik tombol item baris menu.'
  }
]
</script>

